import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Перший час","e":"First Hour","secs":[{"ps":["Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему.","§І три поклони."]},{"h":"Псалом 5","ps":["Глаго́ли моя́ внуши́, Го́споди, разумі́й зва́ніє моє́. Воньми́ гла́су моле́нія моєго́, Царю́ мой і Бо́же мой, я́ко к Тебі́ помолю́ся, Го́споди. Зау́тра усли́ши глас мой, зау́тра предста́ну Ті, і у́зриши м'я. Я́ко Бог не хотя́й беззако́нія, Ти єси́: не присели́ться к Тебі́ лука́внуяй, ніже́ пребу́дуть беззако́нници пред очи́ма Твої́ма: возненави́діл єси́ вся ді́лающия беззако́ніє. Погуби́ши вся глаго́лющия лжу: му́жа крове́й і льсти́ва гнуша́ється Госпо́дь. Аз же мно́жеством ми́лости Твоєя́, вни́ду в дом Твой, поклоню́ся ко хра́му свято́му Твоєму́, в стра́сі Твоє́м. Го́споди, наста́ви м'я пра́вдою Твоє́ю, враг мої́х ра́ди іспра́ви пред Тобо́ю путь мой. Я́ко ність во усті́х їх і́стини, се́рдце їх су́єтно, гроб отве́рст горта́нь їх: язи́ки свої́ми льща́ху. Суди́ їм, Бо́же, да отпаду́ть от ми́слей свої́х, по мно́жеству нече́стія їх ізри́ни я, я́ко преогорчи́ша Тя, Го́споди. І да возвеселя́ться всі упова́ющії на Тя, во вік возра́дуються, і всели́шися в них, і похва́ляться о Тебі́ лю́б'ящії і́м'я Твоє́. Я́ко Ти благослови́ши пра́ведника, Го́споди: я́ко ору́жієм благоволе́нія вінча́л єси́ нас."]},{"h":"Псалом 89","ps":["Го́споди, прибі́жище бил єси́ нам в род і род. Пре́жде да́же гора́м не би́ти і созда́тися землі́ і вселе́нній, і от ві́ка і до ві́ка Ти єси́. Не отврати́ челові́ка во смире́ніє, і рекл єси́: обраті́теся, си́нове челові́честії. Я́ко ти́сяща літ пред очи́ма Твої́ма, Го́споди, я́ко день вчера́шній, і́же мимоі́де, і стра́жа нощна́я. Унічиже́нія їх лі́та бу́дуть. У́тро я́ко трава́ мимоі́деть, у́тро процвіте́ть і пре́йдеть: на ве́чер отпаде́ть ожесті́єть і і́зсхнеть. Я́ко ісче́зохом гні́вом Твої́м, і я́ростію Твоє́ю смути́хомся. Положи́л єси́ беззако́нія на́ша пред Тобо́ю: вік наш в просвіще́ніє лиця́ Твоєго́. Я́ко всі дні́є на́ші оскуді́ша, і гні́вом Твої́м ісчезо́хом, лі́та на́ша я́ко паучи́на поуча́хуся. Дні́є літ на́ших, в ни́хже се́дмдесят літ, а́ще же в си́лах, о́смдесят літ, і мно́жає їх труд і болі́знь: я́ко приї́де кро́тость на ни, і нака́жемся. Кто вість держа́ву гні́ва Твоєго́, і от стра́ха Твоєго́, я́рость Твою́ ісчести́? Десни́цю Твою́ та́ко скажи́ мі, і окова́нния се́рдцем в му́дрости. Обрати́ся, Го́споди, доко́лі? І умоле́н бу́ди на раби́ Твоя́. Іспо́лнихомся зау́тра ми́лости Твоєя́, Го́споди, і возра́довахомся, і возвесели́хомся, во вся дні на́ша возвесели́хомся, за дні в ня́же смири́л ни єси́, лі́та в ня́же ви́діхом зла́я. І при́зри на раби́ Твоя́, і на діла́ Твоя́, і наста́ви си́ни їх. І бу́ди сві́тлость Го́спода Бо́га на́шего на нас, і діла́ рук на́ших іспра́ви на нас, і ді́ло рук на́ших іспра́ви."]},{"h":"Псалом 100","ps":["Ми́лость і суд воспою́ Тебі́, Го́споди. Пою́ і разумі́ю в путі́ непоро́чне, когда́ приі́деши ко мні? Прехожда́х в незло́бії се́рдця моєго́ посреді́ до́му моєго́. Не предлага́х пред очи́ма мої́ма вещ законопресту́пную: творя́щия преступле́ніє возненави́діх. Не прильпе́ мні се́рдце стропти́во, уклоня́ющагося от мене́ лука́ваго не позна́х. Оклевета́ющаго тай і́скренняго своєго́, сего́ ізгоня́х: го́рдим о́ком, і неси́тим се́рдцем, с сим не ядя́х. О́чі мої́ на ві́рния землі́, посажда́ти я со мно́ю: ходя́й по путі́ непоро́чну, сей мі служа́ше. Не жив'я́ше посреді́ до́му моєго́ творя́й горди́ню, глаго́ляй непра́ведная, не ісправля́ше пред очи́ма мої́ма. Во у́трія ізбива́х вся грі́шния землі́, є́же потреби́ти от гра́да Госпо́дня вся ді́лающия беззако́ніє.","Сла́ва, і ни́ні: Аллилу́я, аллилу́я, аллилу́я, сла́ва Тебі́ Бо́же. Три́жди. Покло́ни три. Го́споди, поми́луй, Три́жди. І а́ще у́бо Бог Госпо́дь Поє́ться, глаго́лем: Сла́ва, Тропа́р дне. І ни́ні: Что Тя нарече́м:","А́ще же Аллилу́я, промовляємо цей тропар, глас 6:","Зау́тра усли́ши глас мой, / Царю́ мой і Бо́же мой.","Стих 1: Глаго́ли моя́ внуши́, Го́споди, разумі́й зва́ніє моє́.","Стих 2: Я́ко к Тебі́ помолю́ся, Го́споди.","К сим же стихо́м припіва́єм: Зау́тра усли́ши глас мой: Весь до конця́, і покланя́ємся по єди́ножди.","§Слава, і нині, Богородичен:","Что Тя нарече́м, о Благода́тная? / Не́бо, я́ко возсія́ла єси́ Со́лнце Пра́вди. / Рай, я́ко прозябла́ єси́ цвіт нетлі́нія. / Ді́ву, я́ко пребила́ єси́ нетлі́нна. / Чи́стую Ма́тер, я́ко імі́ла єси́ на святи́х Твої́х об'я́тіях Си́на, всіх Бо́га. / Того́ моли́ спасти́ся душа́м на́шим.","Стопи́ моя́ напра́ви по словесі́ Твоєму́ / і да не облада́єть мно́ю вся́коє беззако́ніє. / Ізба́ви м'я от клевети́ челові́чеськія, / і сохраню́ за́повіді Твоя́. / Лице́ Твоє́ просвіти́ на раба́ Твоєго́ / і нау́чи м'я оправда́нієм Твої́м.","Да іспо́лняться уста́ моя́ хвале́нія Твоєго́, Го́споди, / я́ко да воспою́ сла́ву Твою́, / весь день великолі́піє Твоє́.","§Як співаються ці стихи на Великому посту, написано в Тріоді.","Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь.","§Якщо не Великий піст, промовляємо кондак святого або празника, що трапився. Якщо ж Великий піст або кондака немає:"]},{"h":"У понеділок, вівторок і четвер промовляй цей Богородичен","ps":["Пресла́вную Бо́жию Ма́тер, і святи́х А́нгел Святі́йшую, / немо́лчно воспої́м се́рдцем і усти́, / Богоро́дицю сію́ іспові́дающе, / я́ко воі́стину ро́ждшую нам Бо́га воплоще́нна, / і моля́щуюся непреста́нно о душа́х на́ших."]},{"h":"У середу й п’ятницю промовляй це, глас 4","ps":["Ско́ро предвари́, пре́жде да́же не порабо́тимся враго́м / ху́лящим Тя, і претя́щим нам, Христе́ Бо́же наш, / погуби́ Кресто́м Твої́м борю́щия нас, / да уразумі́ють, ка́ко мо́жеть правосла́вних ві́ра, / моли́твами Богоро́диці, Єди́не Человіколю́бче."]},{"h":"У суботу цей, глас 8","ps":["Я́ко нача́тки єстества́, Насади́телю тва́рі, / вселе́нная прино́сить Ті, Го́споди, богоно́сния му́ченики, / тіх моли́твами в ми́рі глубо́ці / Це́рков Твою́, жи́тельство Твоє́, / Богоро́дицею соблюди́, Многоми́лостиве.","Го́споди, поми́луй, 40.","І́же на вся́коє вре́м'я і на вся́кий час, на Небесі́ і на землі́, покланя́ємий і сла́вимий, Христе́ Бо́же, Долготерпіли́ве, Многоми́лостиве, Многоблагоутро́бне, І́же пра́ведния люб'я́й і грі́шния ми́луяй, І́же вся зови́й ко спасе́нію обіща́нія ра́ди бу́дущих благ. Сам, Го́споди, прийми́ і на́ша в час сей моли́тви і іспра́ви живо́т наш к за́повідем Твої́м, ду́ші на́ша освяти́, тілеса́ очи́сти, помишле́нія іспра́ви, ми́слі очи́сти і ізба́ви нас от вся́кия ско́рби, зол і болі́зней, огради́ нас святи́ми Твої́ми А́нгели, да ополче́нієм їх соблюда́єми і наставля́ємі, дости́гнем в соєдине́ніє ві́ри і в ра́зум непристу́пния Твоєя́ сла́ви, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь.","Го́споди поми́луй, Три́жди. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Свяще́нник возгла́с: Бо́же, уще́дри ни і благослови́ ни, просвіти́ лице́ Твоє́ на ни і поми́луй ни.","І ми глаго́лем: Амі́нь.","§Якщо ж Великий піст, творимо три великі поклони, промовляючи встановлену молитву:","Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н.","§Так само й інших малих — 12. Потім і останній. Усього разом 16.","Та́же: Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь. Го́споди поми́луй, 12."]},{"h":"Священник читає цю молитву","ps":["Христе́, Сві́те І́стинний, просвіща́яй і освяща́яй вся́каго челові́ка, гряду́щаго в мир, да зна́менається на нас світ лиця́ Твоєго́, да в нем у́зрим Світ Непристу́пний: і іспра́ви стопи́ на́ша к ді́ланію за́повідей Твої́х, моли́твами Пречи́стия Твоєя́ Ма́тере, і всіх Твої́х святи́х, амі́нь.","Хор: Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице, / но я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті; / ра́дуйся, Неві́сто Неневі́стная.","Священник: Сла́ва Тебі́, Христе́ Бо́же, упова́ніє на́ше, сла́ва Тебі́.","Хор: Сла́ва, і ни́ні: Го́споди, поми́луй, Три́жди. Благослови́.","§І звершується відпуст."]},{"h":"Кінець першої години.","ps":[]}],"notes":[]},{"u":"Міжчасся першого часу","e":"Interval after the First Hour","secs":[{"ps":["По: Благослове́н Бог: Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь. Го́споди поми́луй, 12. Сла́ва, і ни́ні: Прийді́те, поклоні́мся, Три́жди. І псалми́:"]},{"h":"Псалом 45","ps":["Бог нам Прибі́жище і Си́ла, Помо́щник в ско́рбіх, обрі́тших ни зіло́. Сего́ ра́ди не убої́мся, внегда́ смуща́ється земля́ і прелага́ються го́ри в сердця́ морська́я. Возшумі́ша і см'ято́шася во́ди їх, см'ято́шася го́ри крі́постію Єго́. Рі́чная устремле́нія веселя́ть град Бо́жий: освяти́л єсть селе́ніє Своє́ Ви́шній. Бог посреді́ єго́, і не подви́житься: помо́жеть єму́ Бог у́тро зау́тра. См'ято́шася язи́ци, уклони́шася ца́рствія: даде́ глас Свой Ви́шній, подви́жеся земля́. Госпо́дь сил с на́ми, Засту́пник наш Бог Іа́ковль. Прийді́те і ви́діте діла́ Бо́жия, я́же положи́ чудеса́ на землі́: от'є́мля бра́ні до коне́ць землі́, лук сокруши́ть і сло́мить ору́жіє, і щити́ сожже́ть огне́м. Упраздні́теся і разумі́йте, я́ко Аз єсьм Бог: вознесу́ся во язи́ціх, вознесу́ся на землі́. Госпо́дь сил с на́ми, Засту́пник наш Бог Іа́ковль."]},{"h":"Псалом 91","ps":["Бла́го єсть іспові́датися Го́сподеві, і пі́ти і́мені Твоєму́, Ви́шній: возвіща́ти зау́тра ми́лость Твою́ і і́стину Твою́ на вся́ку нощ, в десятостру́ннім псалти́ри с пі́снію в гу́сліх. Я́ко возвесели́л м'я єси́, Го́споди, в творе́нії Твоє́м, і в ді́ліх руку́ Твоє́ю возра́дуюся. Я́ко возвели́чишася діла́ Твоя́, Го́споди, зіло́ углуби́шася помишле́нія Твоя́. Муж безу́мен не позна́єть, і неразу́мив не разумі́єть сих. Внегда́ прозябо́ша грі́шници я́ко трава́, і пронико́ша всі ді́лающії беззако́ніє: я́ко да потреб'я́ться во вік ві́ка. Ти же Ви́шній во вік, Го́споди. Я́ко се вразі́ Твої́, Го́споди, я́ко се вразі́ Твої́ поги́бнуть, і рази́дуться всі ді́лающії беззако́ніє. І вознесе́ться я́ко єдиноро́га рог мой, і ста́рость моя́ в єле́ї масти́ті. І воззрі́ о́ко моє́ на враги́ моя́, і востаю́щия на м'я лука́внующия усли́шить у́хо моє́. Пра́ведник я́ко фі́нікс процвіте́ть, я́ко кедр, і́же в Лива́ні, умно́житься. Насажде́ні в дому́ Госпо́дні, во дво́ріх Бо́га на́шего процвіту́ть, єще́ умно́жаться в ста́рости масти́ті, і благоприє́млюще бу́дуть. Да возвістя́ть, я́ко прав Госпо́дь Бог наш, і ність непра́вди в Нем."]},{"h":"Псалом 92","ps":["Госпо́дь воцари́ся, в лі́поту облече́ся: облече́ся Госпо́дь в си́лу і препоя́сася, і́бо утверди́ вселе́нную, я́же не подви́житься. Гото́в Престо́л Твой отто́лі: от ві́ка Ти єси́. Воздвиго́ша рі́ки, Го́споди, воздвиго́ша рі́ки гла́си своя́. Во́зьмуть рі́ки сотре́нія своя́, от гласо́во вод мно́гих. Ди́вни висоти́ морські́я, ди́вен во висо́ких Госпо́дь. Свиді́нія Твоя́ уві́ришася зіло́, до́му Твоєму́ подоба́єть святи́ня, Го́споди, в долготу́ дній.","Сла́ва і ни́ні: Трисвято́є. Покло́ни три. Пресвята́я Тро́йце: По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь."]},{"h":"І ці тропарі, глас 6","ps":["Поми́луй нас, Го́споди, поми́луй нас; / вся́каго бо отві́та недоумі́юще, / сію́ Ті моли́тву я́ко Влади́ці, грі́шнії прино́сим: / поми́луй нас.","Слава: Го́споди, поми́луй нас, / на Тя бо упова́хом; / не прогні́вайся на ни зіло́, / ніже́ пом'яни́ беззако́ній на́ших, / но при́зри і ни́ні я́ко благоутро́бен, / і ізба́ви ни от враг на́ших; / Ти бо єси́ Бог наш, / і ми лю́діє Твої́, / всі діла́ руку́ Твоє́ю, / і і́м'я Твоє́ призива́єм.","І нині: Милосе́рдія две́рі отве́рзи нам, / благослове́нная Богоро́дице, / наді́ющіїся на Тя да не поги́бнем, / но да ізба́вимся Тобо́ю от бід: / Ти бо єси́ спасе́ніє ро́да христия́нськаго.","Го́споди, поми́луй, 40. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Моли́твами святи́х оте́ць на́ших, Го́споди, Ісу́се Христе́, Бо́же наш, поми́луй нас. І ми: Амі́нь."]},{"h":"Потім три великі поклони, промовляючи на кожному поклоні молитву прп. Єфрема","ps":["Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н."]},{"h":"Потім молитва святого Василія Великого","ps":["Бо́же Ві́чний, Безнача́льний і Присносу́щний Сві́те, вся́кия тва́ри Соді́телю, ми́лости Істо́чниче, бла́гости пучи́но, і человіколю́бія неізслі́димая бе́здно: просвіти́ на ни світ лиця́ Твоєго́, Го́споди, возсія́й в сердця́х на́ших у́мноє Со́лнце пра́вди, і Твоєго́ весе́лія ду́ші на́ша іспо́лни, і научи́ нас Твої́м поуча́тися при́сно і віща́ти судьба́м, і іспові́датися Тебі́ ви́ну, на́шему Влади́ці і Благоді́телю. Рук на́ших діла́ к Твоє́й іспра́ви во́лі, і ді́яти нам Тебе́ благоуго́дная і любе́зная благопоспіши́, да і о на́шем недосто́їнстві просла́виться Твоє́ Пресвято́є І́м'я, Отця́ і Си́на і Свята́го Ду́ха, Єди́наго Божества́ же і Ца́рства: Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, амі́нь."]},{"h":"Потім і цю, того самого автора","ps":["Посила́яй світ, і і́деть, возсіява́яй со́лнце на пра́ведния і непра́ведния, лука́вия же і благи́я: творя́й у́тро, і просвіща́яй всю вселе́нную, просвіти́ і на́ша сердця́, Влади́ко всіх: да́руй нам в настоя́щий день благоугоди́ти Тебі́, сохраня́яй нас от вся́каго гріха́, і вся́каго лука́ваго дія́нія, ізбавля́яй нас от вся́кия стріли́ летя́щия во дні, і от вся́кия сопроти́вния си́ли, моли́твами Всепречи́стия Влади́чиці на́шея Богоро́диці, невеще́ственних Твої́х служи́телей, і пренебе́сних сил і всіх святи́х, от ві́ка Тебі́ благоугоди́вших. Твоє́ бо єсть, є́же ми́ловати і спаса́ти ни, Бо́же наш, і Тебі́ сла́ву возсила́єм, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Священник: Сла́ва Тебі́, Христе́ Бо́же, упова́ніє на́ше, сла́ва Тебі́.","І ми: Сла́ва, і ни́ні: Го́споди, поми́луй, Три́жди. Благослови́.","§І звершується малий відпуст."]}],"notes":[]},{"u":"Третій час","e":"Third Hour","secs":[{"ps":["По є́же благослови́ти свяще́ннику, глаго́лем: Амі́нь.","Сла́ва Тебі́, Бо́же наш, сла́ва Тебі́.","Царю́ Небе́сний, Уті́шителю, Ду́ше і́стини, І́же везді́ сий і вся ісполня́яй, Сокро́вище благи́х і жи́зні Пода́телю, прийди́ і всели́ся в ни, і очи́сти ни от вся́кия скве́рни, і спаси́, Бла́же, ду́ші на́ша.","Святи́й Бо́же, Святи́й Крі́пкий, Святи́й Безсме́ртний, поми́луй нас. Три́жди.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас; Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй, Три́жди. Сла́ва, і ни́ні:","О́тче наш, І́же єси́ на Небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на Небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь.","Та́же, Го́споди, поми́луй, 12, Сла́ва, і ни́ні:","Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему."]},{"h":"Псалом 16","ps":["Усли́ши, Го́споди, пра́вду мою́, воньми́ моле́нію моєму́, внуши́ моли́тву мою́ не во устна́х льсти́вих. От лиця́ Твоєго́ судьба́ моя́ ізи́деть, о́чі мої́ да ви́дита правоти́. Іскуси́л єси́ се́рдце моє́, посіти́л єси́ но́щію, іскуси́л м'я єси́, і не обрі́теся во мні непра́вда. Я́ко да не возглаго́лють уста́ моя́ діл челові́чеських, за словеса́ усте́н Твої́х аз сохрани́х путі́ же́стоки. Соверши́ стопи́ моя́ во стезя́х Твої́х, да не подви́жуться стопи́ моя́. Аз воззва́х, я́ко усли́шал м'я єси́, Бо́же, приклони́ у́хо Твоє́ мні і усли́ши глаго́ли моя́. Удиви́ ми́лості Твоя́, спаса́яй упова́ющия на Тя от проти́в'ящихся десни́це Твоє́й. Сохрани́ м'я, Го́споди, я́ко зі́ницю о́ка, в кро́ві крилу́ Твоє́ю покри́єши м'я. От лиця́ нечести́вих остра́стших м'я, вразі́ мої́ ду́шу мою́ одержа́ша. Тук свой затвори́ша, уста́ їх глаго́лаша горди́ню. Ізгоня́щії м'я ни́ні обидо́ша м'я, о́чі свої́ возложи́ша уклони́ти на зе́млю. Об'я́ша м'я я́ко лев гото́в на лов і я́ко ски́мен обита́яй в та́йних. Воскресни́, Го́споди, предвари́ я і запни́ їм, ізба́ви ду́шу мою́ от нечести́ваго, ору́жіє Твоє́ от враг руки́ Твоєя́. Го́споди, от ма́лих от землі́, разділи́ я в животі́ їх, і сокрове́нних Твої́х іспо́лнися чре́во їх, наси́тишася сино́в, і оста́виша оста́нки младе́нцем свої́м. Аз же пра́вдою явлю́ся лицю́ Твоєму́, наси́щуся, внегда́ яви́ти мі ся сла́ві Твоє́й."]},{"h":"Псалом 24","ps":["К Тебі́, Го́споди, воздвиго́х ду́шу мою́, Бо́же мой, на Тя упова́х, да не постижу́ся во вік, ніже́ да посмію́ть мі ся вразі́ мої́, і́бо всі терп'я́щії Тя не постидя́ться. Да постидя́ться беззако́ннующії вотще́. Путі́ Твоя́, Го́споди, скажи́ мі, і стезя́м Твої́м научи́ м'я. Наста́ви м'я на і́стину Твою́, і научи́ м'я, я́ко Ти єси́ Бог Спас мой, і Тебі́ терпі́х весь день. Пом'яни́ щедро́ти Твоя́, Го́споди, і ми́лості Твоя́, я́ко от ві́ка суть. Гріх ю́ности моєя́, і неві́дінія моєго́ не пом'яни́, по ми́лості Твоє́й пом'яни́ м'я Ти, ра́ди бла́гости Твоєя́, Го́споди. Благ і прав Госпо́дь, сего́ ра́ди законоположи́ть согріша́ющим на путі́. Наста́вить кро́ткия на суд, научи́ть кро́ткия путе́м Свої́м. Всі путіє́ Госпо́дні ми́лость і і́стина, взиска́ющим заві́та Єго́, і свиді́нія Єго́. Ра́ди і́мене Твоєго́, Го́споди, і очи́сти гріх мой, мног бо єсть. Кто єсть челові́к боя́йся Го́спода? Законоположи́ть єму́ на путі́, єго́же ізво́ли. Душа́ єго́ во благи́х водвори́ться, і сі́м'я єго́ наслі́дить зе́млю. Держа́ва Госпо́дь боя́щихся Єго́, і заві́т Єго́ яви́ть їм. О́чі мої́ ви́ну ко Го́споду, я́ко Той істо́ргнеть от сі́ті но́зі мої́. При́зри на м'я і поми́луй м'я, я́ко єдиноро́д і нищ єсьм аз. Ско́рбі се́рдця моєго́ умно́жишася, от нужд мої́х ізведи́ м'я. Виждь смире́ніє моє́, і труд мой, і оста́ви вся гріхи́ моя́. Виждь враги́ моя́, я́ко умно́жишася, і ненавиді́нієм непра́ведним возненави́діша м'я. Сохрани́ ду́шу мою́, і ізба́ви м'я, да не постижу́ся, я́ко упова́х на Тя. Незло́бивії і пра́вії приліпля́хуся мні, я́ко потерпі́х Тя, Го́споди. Ізба́ви, Бо́же, Ізра́їля от всіх скорбе́й єго́."]},{"h":"Псалом 50","ps":["Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́. Найпа́че оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я; я́ко беззако́ніє моє́ аз зна́ю, і гріх мой предо мно́ю єсть ви́ну. Тебі́ Єди́ному согріши́х і лука́воє пред Тобо́ю сотвори́х, я́ко да оправди́шися во словесі́х Твої́х, і побіди́ши внегда́ суди́ти Ті. Се бо, в беззако́ніїх зача́т єсьм, і во грісі́х роди́ м'я ма́ти моя́. Се бо, і́стину возлюби́л єси́; безві́стная і та́йная прему́дрости Твоєя́ яви́л мі єси́. Окропи́ши м'я іссо́пом, і очи́щуся; оми́єши м'я, і па́че сні́га убілю́ся. Слу́ху моєму́ да́си ра́дость і весе́ліє; возра́дуються ко́сті смире́нния. Отврати́ лице́ Твоє́ от гріх мої́х і вся беззако́нія моя́ очи́сти. Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й. Не отве́ржи мене́ от лиця́ Твоєго́ і Ду́ха Твоєго́ Свята́го не отими́ от мене́. Возда́ждь мі ра́дость спасе́нія Твоєго́ і Ду́хом Влади́чним утверди́ м'я. Научу́ беззако́нния путе́м Твої́м, і нечести́вії к Тебі́ обратя́ться. Ізба́ви м'я от крове́й, Бо́же, Бо́же спасе́нія моєго́; возра́дується язи́к мой пра́вді Твоє́й. Го́споди, устні́ мої́ отве́рзеши, і уста́ моя́ возвістя́ть хвалу́ Твою́. Я́ко а́ще би восхоті́л єси́ же́ртви, дал бих у́бо: всесожже́нія не благоволи́ши. Же́ртва Бо́гу дух сокруше́н; се́рдце сокруше́нно і смире́нно Бог не унічижи́ть. Ублажи́, Го́споди, благоволе́нієм Твої́м Сіо́на, і да сози́ждуться сті́ни Ієрусали́мськія. Тогда́ благоволи́ши же́ртву пра́вди, возноше́ніє і всесожега́ємая; тогда́ возложа́ть на олта́р Твой тельці́.","Сла́ва, і ни́ні: Аллилу́я, Три́жди. Го́споди, поми́луй, Три́жди.","І а́ще у́бо Бог Госпо́дь Поє́ться, глаго́ли: Сла́ва, Дне тропа́р. І ни́ні: Богоро́дице, Ти єси́ Лоза́ І́стинная:","А́ще же Аллилу́я, промовляй цей тропар, глас 6:","Го́споди, і́же Пресвята́го Твоєго́ Ду́ха / в тре́тій час Апо́столом Твої́м низпосла́вий: / Того́, Благи́й, не отими́ от нас, / но обнови́ нас, моля́щих Ті ся.","Стих 1: Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й.","Стих 2: Не отве́ржи мене́ от лиця́ Твоєго́, і Ду́ха Твоєго́ Свята́го не отими́ от мене́.","К сим же стихо́м припіва́єм: Го́споди, І́же Пресвята́го Твоєго́ Ду́ха: Весь до конця́, і покланя́ємся по єди́ножди.","§Потім: Слава, і нині, Богородичен:","Богоро́дице, Ти єси́ лоза́ і́стинная, / возрасти́вшая нам Плод живота́, / Тебі́ мо́лимся: / моли́ся, Влади́чице, со святи́ми апо́столи / поми́ловати ду́ші на́ша.","Госпо́дь Бог благослове́н, / благослове́н Госпо́дь день дне, / поспіши́ть нам Бог спасе́ній на́ших, / Бог наш, Бог спаса́ти.","Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь.","§Кондак святого дня або празника."]},{"h":"Якщо ж піст, промовляємо ці тропарі, глас 8","ps":["Благослове́н єси́ Христе́ Бо́же наш, / І́же прему́дри ловці́ явле́й, / низпосла́в їм Ду́ха Свята́го, / і ті́ми уловле́й вселе́нную, / Человіколю́бче, сла́ва Тебі́.","Слава: Ско́роє і ізві́стноє даждь утіше́ніє рабо́м Твої́м, Ісу́се, / внегда́ унива́ти духо́м на́шим, / не разлуча́йся от душ на́ших в ско́рбіх, / не удаля́йся от ми́слей на́ших во обстоя́ніїх, но при́сно нас предвари́. / Прибли́жися нам, прибли́жися везді́ Сий, / я́коже со Апо́столи Твої́ми всегда́ єси́, / си́це і Тебі́ жела́ющим соєдини́ Себі́, Ще́дре, да совоку́плени Тебі́ поє́м / і славосло́вим Всесвята́го Ду́ха Твоєго́.","І нині: Наде́жда, і предста́тельство, і прибі́жище христия́н, необори́мая стіна́, / ізнемога́ющим приста́нище небу́рноє, Ти єси́ Богоро́дице Пречи́стая, / но я́ко мир Спаса́ющая непреста́нною Твоє́ю моли́твою, / пом'яни́ і нас, Ді́во Всепі́тая.","Го́споди, поми́луй, 40.","І́же на вся́коє вре́м'я і на вся́кий час, на Небесі́ і на землі́, покланя́ємий і сла́вимий, Христе́ Бо́же, Долготерпіли́ве, Многоми́лостиве, Многоблагоутро́бне, І́же пра́ведния люб'я́й і грі́шния ми́луяй, І́же вся зови́й ко спасе́нію обіща́нія ра́ди бу́дущих благ. Сам, Го́споди, прийми́ і на́ша в час сей моли́тви і іспра́ви живо́т наш к за́повідем Твої́м, ду́ші на́ша освяти́, тілеса́ очи́сти, помишле́нія іспра́ви, ми́слі очи́сти і ізба́ви нас от вся́кия ско́рби, зол і болі́зней, огради́ нас святи́ми Твої́ми А́нгели, да ополче́нієм їх соблюда́єми і наставля́ємі, дости́гнем в соєдине́ніє ві́ри і в ра́зум непристу́пния Твоєя́ сла́ви, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь.","Го́споди поми́луй, Три́жди. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Свяще́нник возгла́с: Моли́твами святи́х оте́ць на́ших, Го́споди, Ісу́се Христе́, Бо́же наш, поми́луй нас.","І ми: Амі́нь."]},{"h":"Якщо ж Великий піст, творимо три великі поклони, промовляючи молитву","ps":["Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н.","Потім 12 малих поклонів, промовляючи на кожному поклоні: Бо́же, очи́сти м'я грі́шнаго.","І па́ки посліди́ моли́тву всю: Го́споди і Влади́ко живота́ моєго́:","§І один великий поклін. По закінченні ж поклонів промовляємо:"]},{"h":"Молитва святого Мардарія","ps":["Влади́ко Бо́же О́тче Вседержи́телю, Го́споди Си́не Єдиноро́дний Ісу́се Христе́, і Святи́й Ду́ше, Єди́но Боже́ство, Єди́на Си́ла, поми́луй м'я, грі́шнаго, і ї́миже ві́си судьба́ми, спаси́ м'я, недосто́йнаго раба́ Твоєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь."]},{"h":"Кінець третьої години.","ps":[]}],"notes":[]},{"u":"Міжчасся третього часу","e":"Interval after the Third Hour","secs":[{"ps":["По: Благослове́н Бог: Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь. Го́споди поми́луй, 12. Сла́ва, і ни́ні: Прийді́те, поклоні́мся, Три́жди. І псалми́:"]},{"h":"Псалом 29","ps":["Вознесу́ Тя, Го́споди, я́ко под'я́л м'я єси́, і не возвесели́л єси́ враго́в мої́х о мні. Го́споди Бо́же мой, воззва́х к Тебі́, і ісціли́л м'я єси́. Го́споди, возве́л єси́ от а́да ду́шу мою́, спасл м'я єси́ от низходя́щих в ров. По́йте Го́сподеві, преподо́бнії Єго́, і іспові́дайте па́м'ять святи́ні Єго́. Я́ко гнів в я́рости Єго́, і живо́т во во́лі Єго́: ве́чер водвори́ться плач, і зау́тра ра́дость. Аз же ріх во оби́лії моє́м: не подви́жуся во вік. Го́споди, во́лею Твоє́ю пода́ждь добро́ті моє́й си́лу. Отврати́л же єси́ лице́ Твоє́, і бих смуще́н. К Тебі́, Го́споди, воззову́, і к Бо́гу моєму́ помолю́ся. Ка́я по́льза в кро́ві моє́й, внегда́ сходи́ти мі во істлі́ніє? Єда́ іспові́стся Тебі́ персть, іли́ возвісти́ть і́стину Твою́? Сли́ша Госпо́дь і поми́лова м'я: Госпо́дь бисть Помо́щник мой. Обрати́л єси́ плач мой в ра́дость мні: растерза́л єси́ вре́тище моє́, і препоя́сал м'я єси́ весе́лієм. Я́ко да воспоє́ть Тебі́ сла́ва моя́, і не умилю́ся: Го́споди Бо́же мой, во вік іспові́мся Тебі́."]},{"h":"Псалом 31","ps":["Блаже́нні, ї́хже оста́вишася беззако́нія і ї́хже прикри́шася гріси́. Блаже́н муж, єму́же не вміни́ть Госпо́дь гріха́, ніже́ єсть во усті́х єго́ лесть. Я́ко умолча́х, обетша́ша ко́сті моя́, от є́же зва́ти мі весь день. Я́ко день і нощ отяготі́ на мні рука́ Твоя́, возврати́хся на страсть, єгда́ унзе́ мі терн. Беззако́ніє моє́ позна́х і гріха́ моєго́ не покри́х, ріх: іспові́м на м'я беззако́ніє моє́ Го́сподеві, і Ти оста́вил єси́ нече́стіє се́рдця моєго́. За то помо́литься к Тебі́ всяк преподо́бний во вре́м'я благопотре́бно: оба́че в пото́пі вод мно́гих к нему́ не прибли́жаться. Ти єси́ прибі́жище моє́ от ско́рби обдержа́щия м'я: ра́досте моя́, ізба́ви м'я от обише́дших м'я. Вразумлю́ тя і наста́влю тя на путь сей, во́ньже по́йдеши, утвержу́ на тя о́чі Мої́. Не бу́діте я́ко конь і меск, і́мже ність ра́зума: брозда́ми і уздо́ю че́люсти їх востя́гнеши, не приближа́ющихся к тебі́. Мно́гі ра́ни грі́шному, упова́ющаго же на Го́спода ми́лость оби́деть. Веселі́теся о Го́споді, і ра́дуйтеся, пра́веднії, і хвалі́теся, всі пра́вії се́рдцем."]},{"h":"Псалом 60","ps":["Усли́ши, Бо́же, моле́ніє моє́, воньми́ моли́тві моє́й. От коне́ць землі́ к Тебі́ воззва́х, внегда́ уни́ се́рдце моє́, на ка́мень возне́сл м'я єси́, наста́вил м'я єси́. Я́ко бил єси́ упова́ніє моє́, столп крі́пости от лиця́ вра́жия. Вселю́ся в селе́нії Твоє́м во ві́ки, покри́юся в кро́ві крил Твої́х. Я́ко Ти, Бо́же, усли́шал єси́ моли́тви моя́, дал єси́ достоя́ніє боя́щимся і́мене Твоєго́. Дні на дні царе́ви приложи́ши, лі́та єго́ до дне ро́да і ро́да. Пребу́деть во вік пред Бо́гом, ми́лость і і́стину Єго́ кто взи́щеть? Та́ко воспою́ і́мені Твоєму́ во ві́ки, возда́ти мі моли́тви моя́ день от дне.","Сла́ва, і ни́ні: Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь."]},{"h":"Ці тропарі, глас 4","ps":["Бо́же оте́ць на́ших, / творя́й при́сно с на́ми по Твоє́й кро́тости, / не отста́ви ми́лость Твою́ от нас, / но моли́твами їх / в ми́рі упра́ви живо́т наш.","Сла́ва: Му́ченици Твої́, Го́споди, / во страда́ніїх свої́х вінці́ прия́ша нетлі́нния от Тебе́, Бо́га на́шего: / іму́ще бо крі́пость Твою́, / мучи́телей низложи́ша, / сокруши́ша і де́монов немощни́я де́рзости: / тіх моли́твами / спаси́ ду́ші на́ша.","І ни́ні: Стіна́ Необори́мая нам христия́ном єси́ Богоро́дице Ді́во, / к Тебі́ бо прибіга́юще, невреди́ми пребива́єм, / і па́ки согріша́юще, і́мами Тя Моли́твенницю. / Тім благодаря́ще вопіє́м Ті: / ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю.","Го́споди поми́луй, 40. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Моли́твами святи́х оте́ць на́ших, Го́споди, Ісу́се Христе́, Бо́же наш, поми́луй нас. І ми: Амі́нь."]},{"h":"Потім три великі поклони, промовляючи на кожному поклоні молитву прп. Єфрема","ps":["Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н."]},{"h":"Потім ця молитва святого Василія Великого","ps":["Го́споди Бо́же наш, Твой мир да́вий челові́ком, і Пресвята́го Ду́ха дар Твої́м ученико́м і Апо́столом низпосла́вий, і сих устні́ о́гненними язи́ки разве́рзий си́лою Твоє́ю, разве́рзі і нас, грі́шних, устні́, і научи́ ни, ка́ко подоба́єть, і о ни́хже тре́бі єсть моли́тися: упра́ви на́шу жизнь, благооти́шноє обурева́ємих приста́нище, і скажи́ нам путь, во́ньже по́йдем, і дух прав обнови́ во утро́бах на́ших, і Ду́хом Влади́чним ми́слі на́шея утверди́ поползнове́ніє, да на всяк день Ду́хом Твої́м Благи́м к поле́зному наставля́ємі, сподо́бимся твори́ти за́повіді Твоя́, і Твоє́ при́сно помина́ти сла́вноє і іспита́тельноє прише́ствіє соді́янних на́ми челові́ки, і не прельща́тися тлі́ющими ми́ра сего́ красота́ми, но бу́дущих жела́ти восприя́тія укріпи́ сокро́вищ. Я́ко благослове́н єси́ і хва́лен от всіх святи́х Твої́х, во ві́ки віко́в, амі́нь."]}],"notes":[]},{"u":"Шостий час","e":"Sixth Hour","secs":[{"ps":["Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему."]},{"h":"І псалми: псалом 53","ps":["Бо́же, во і́м'я Твоє́ спаси́ м'я, і в си́лі Твоє́й суди́ мі. Бо́же, усли́ши моли́тву мою́, внуши́ глаго́ли уст мої́х. Я́ко чу́ждії воста́ша на м'я і крі́пції взиска́ша ду́шу мою́, і не предложи́ша Бо́га пред собо́ю. Се бо Бог помога́єть мі, і Госпо́дь Засту́пник душі́ моє́й. Отврати́ть зла́я враго́м мої́м, і́стиною Твоє́ю потреби́ їх. Во́лею пожру́ Тебі́, іспові́мся і́мені Твоєму́, Го́споди, я́ко бла́го, я́ко от вся́кия печа́лі ізба́вил м'я єси́, і на враги́ моя́ воззрі́ о́ко моє́."]},{"h":"Псалом 54","ps":["Внуши́, Бо́же, моли́тву мою́ і не пре́зри моле́нія моєго́. Воньми́ мі і усли́ши м'я: возскорбі́х печа́лію моє́ю і см'ято́хся. От гла́са вра́жия і от стуже́нія грі́шнича, я́ко уклони́ша на м'я беззако́ніє і во гні́ві враждова́ху мі. Се́рдце моє́ см'яте́ся во мні і боя́знь сме́рті нападе́ на м'я. Страх і тре́петь при́йде на м'я і покри́ м'я тьма. І ріх: кто дасть мі крилі́, я́ко голуби́ні, і полещу́, і почи́ю? Се удали́хся бі́гая і водвори́хся в пусти́ні. Ча́ях Бо́га, спаса́ющаго м'я от малоду́шія і от бу́рі. Потопи́, Го́споди, і разділи́ язи́ки їх: я́ко ви́діх беззако́ніє і преріка́ніє во гра́ді. Днем і но́щію оби́деть ї по стіна́м єго́. Беззако́ніє і труд посреді́ єго́ і непра́вда. І не оскуді́ от стогн єго́ ли́хва і лесть. Я́ко а́ще би враг поноси́л мі, претерпі́л бих у́бо, і а́ще би ненави́дяй м'я на м'я велері́чевал, укри́л бих ся от него́. Ти же, челові́че равноду́шне, влади́ко мой і зна́ємий мой, і́же ку́пно наслажда́лся єси́ со мно́ю бра́шен, в дому́ Бо́жії ходи́хом єдиномишле́нієм. Да при́йдеть же смерть на ня, і да сни́дуть во ад жи́ви, я́ко лука́вство в жили́щах їх, посреді́ їх. Аз к Бо́гу воззва́х, і Госпо́дь усли́ша м'я. Ве́чер і зау́тра, і полу́дне пові́м, і возвіщу́, і усли́шить глас мой. Ізба́вить ми́ром ду́шу мою́ от приближа́ющихся мні, я́ко во мно́зі бя́ху со мно́ю. Усли́шить Бог і смири́ть я, Сий пре́жде вік. Ність бо їм ізміне́нія, я́ко не убоя́шася Бо́га. Простре́ ру́ку свою́ на воздая́ніє, оскверни́ша заві́т Єго́. Разділи́шася от гні́ва лиця́ Єго́, і прибли́жишася сердця́ їх, ум'я́кнуша словеса́ їх па́че єле́я, і та суть стрі́ли. Возве́рзі на Го́спода печа́ль твою́, і Той тя препита́єть, не дасть во вік молви́ пра́веднику. Ти же, Бо́же, низведе́ши їх во студене́ць істлі́нія, му́жіє крове́й і льсти не преполов'я́ть дній свої́х. Аз же, Го́споди, упова́ю на Тя."]},{"h":"Псалом 90","ps":["Живи́й в по́мощі Ви́шняго, в кро́ві Бо́га Небе́снаго водвори́ться. Рече́ть Го́сподеві: Засту́пник мой єси́ і Прибі́жище моє́, Бог мой, і упова́ю на Него́. Я́ко Той ізба́вить тя от сі́ті ло́вчі і от словесе́ м'яте́жна, плещма́ Свої́ма осіни́ть тя, і под крилі́ Єго́ наді́єшися: ору́жієм оби́деть тя і́стина Єго́. Не убої́шися от стра́ха нощна́го, от стріли́ летя́щия во дні, от ве́щі во тьмі преходя́щия, от сря́ща і бі́са полу́деннаго. Паде́ть от страни́ твоєя́ ти́сяща, і тьма одесну́ю тебе́, к тебі́ же не прибли́житься, оба́че очи́ма твої́ма смо́триши, і воздая́ніє грі́шников у́зриши. Я́ко Ти, Го́споди, упова́ніє моє́, Ви́шняго положи́л єси́ прибі́жище твоє́. Не при́йдеть к тебі́ зло і ра́на не прибли́житься тілесі́ твоєму́, я́ко А́нгелом Свої́м запові́сть о тебі́, сохрани́ти тя во всіх путеіх твої́х. На рука́х во́зьмуть тя, да не когда́ преткне́ши о ка́мень но́гу твою́, на а́спида і васили́ска насту́пиши, і попере́ши льва і змі́я. Я́ко на М'я упова́ і ізба́влю ї, покри́ю ї, я́ко позна́ і́м'я Моє́. Воззове́ть ко Мні і усли́шу єго́, с ним єсьм в ско́рбі, ізму́ єго́ і просла́влю єго́, долгото́ю дній іспо́лню єго́ і явлю́ єму́ спасе́ніє Моє́.","Сла́ва, і ни́ні: Аллилу́я, аллилу́я, аллилу́я, сла́ва Тебі́ Бо́же. Три́жди. Го́споди поми́луй, Три́жди. І а́ще поє́ться, Бог Госпо́дь, Глаго́лем: Сла́ва, Тропа́р дне."]},{"h":"Якщо ж «Алилуя», промовляємо цей тропар, глас 2","ps":["І́же в шести́й день же і час, / на кресті́ Пригвожде́й / в раї́ дерзнове́нний Ада́мов гріх, / і согріше́ній на́ших рукописа́ніє раздери́, / Христе́ Бо́же, і спаси́ нас.","Стих 1: Внуши́, Бо́же, моли́тву мою́, і не пре́зри моле́нія моєго́.","Стих 2: Аз к Бо́гу воззва́х, і Госпо́дь усли́ша м'я.","§Слава, і нині, Богородичен:","Я́ко не і́мами дерзнове́нія за премно́гия гріхи́ на́ша, / Ти і́же от Тебе́ Ро́ждшагося моли́, Богоро́дице Ді́во, / мно́го бо мо́жеть моле́ніє Ма́тернєє ко благосе́рдію Влади́ки. / Не пре́зри грі́шних мольби́, Всечи́стая, / я́ко ми́лостив єсть і спасти́ моги́й, / І́же і страда́ти о нас ізво́ливий.","Ско́ро да предваря́ть ни щедро́ти Твоя́, Го́споди, / я́ко обнища́хом зіло́; / помози́ нам, Бо́же, Спа́се наш, / сла́ви ра́ди І́мене Твоєго́, Го́споди, ізба́ви нас / і очи́сти гріхи́ на́ша, І́мене ра́ди Твоєго́.","Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь. Конда́к дне свята́го."]},{"h":"Якщо піст, то в понеділок, вівторок і четвер промовляємо ці тропарі, глас 2","ps":["Спасе́ніє соді́лал єси́ посреді́ землі́, Христе́ Бо́же, / на Кресті́ пречи́стії ру́ці Твої́ просте́рл єси́, / собира́я вся язи́ки, зову́щия: / Го́споди, сла́ва Тебі́.","Слава: Пречи́стому о́бразу Твоєму́ покланя́ємся Благи́й, / прося́ще проще́нія прегріше́ній на́ших, Христе́ Бо́же, / во́лею бо благоволи́л єси́ пло́тію взи́ти на Крест, / да ізба́виши, я́же созда́л єси́, от рабо́ти вра́жия. / Тім благода́рственно вопіє́м Ті: / ра́дости іспо́лнил єси́ вся, Спа́се наш, / прише́дий спасти́ мир.","І нині: Милосе́рдія су́щи істо́чник, / ми́лости сподо́би нас, Богоро́дице, / при́зри на лю́ди согреши́вшия, / яви́ я́ко при́сно си́лу Твою́: / на Тя бо упова́юще, ра́дуйся вопіє́м Ті, / я́коже іногда́ Гавриї́л безпло́тних архістрати́г."]},{"h":"У середу й п’ятницю замість «Милосе́рдія су́щи» — Хрестобогородичен, глас 2","ps":["Препросла́влена єси́, Богоро́дице Ді́во, поє́м Тя, / Кресто́м бо Си́на Твоєго́ низложи́ся ад, і смерть умертви́ся, / умерщвле́ннії воста́хом, і живота́ сподо́бихомся, / рай восприя́хом, дре́внєє наслажде́ніє. / Тім благодаря́ще, славосло́вим я́ко держа́внаго Христа́ Бо́га на́шего, / і єди́наго Многоми́лостиваго.","Го́споди поми́луй, 40.","І́же на вся́коє вре́м'я і на вся́кий час, на Небесі́ і на землі́, покланя́ємий і сла́вимий, Христе́ Бо́же, Долготерпіли́ве, Многоми́лостиве, Многоблагоутро́бне, І́же пра́ведния люб'я́й і грі́шния ми́луяй, І́же вся зови́й ко спасе́нію обіща́нія ра́ди бу́дущих благ. Сам, Го́споди, прийми́ і на́ша в час сей моли́тви і іспра́ви живо́т наш к за́повідем Твої́м, ду́ші на́ша освяти́, тілеса́ очи́сти, помишле́нія іспра́ви, ми́слі очи́сти і ізба́ви нас от вся́кия ско́рби, зол і болі́зней, огради́ нас святи́ми Твої́ми А́нгели, да ополче́нієм їх соблюда́єми і наставля́ємі, дости́гнем в соєдине́ніє ві́ри і в ра́зум непристу́пния Твоєя́ сла́ви, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь.","Посе́м: Го́споди поми́луй, Три́жди. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Моли́твами святи́х оте́ць на́ших, Го́споди, Ісу́се Христе́, Бо́же наш, поми́луй нас.","І ми: Амі́нь.","§І поклони, як сказано, якщо піст:","Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н.","§Так само й інших малих — 12."]},{"h":"Потім молитва святого Василія Великого","ps":["Бо́же і Го́споди сил і всея́ тва́рі Соді́телю, І́же за милосе́рдіє безприкла́дния ми́лости Твоєя́ Єдиноро́днаго Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, низпосла́вий на спасе́ніє ро́да на́шего, і честни́м Єго́ Кресто́м рукописа́ніє гріх на́ших растерза́вий, і побіди́вий тім нача́ла і вла́сті тьми. Сам, Влади́ко Человіколю́бче, прийми́ і нас, грі́шних, благода́рственния сія́ і моле́бния моли́тви і ізба́ви нас от вся́каго всегуби́тельнаго і мра́чнаго прегріше́нія і всіх озло́бити нас і́щущих ви́димих і неви́димих враг. Пригвозди́ стра́ху Твоєму́ пло́ті на́ша і не уклони́ серде́ць на́ших в словеса́ іли́ помишле́нія лука́вствія, но любо́вію Твоє́ю уязви́ ду́ші на́ша, да, к Тебі́ всегда́ взира́юще і є́же от Тебе́ сві́том наставля́ємі, Тебі́, непристу́пнаго і присносу́щнаго зря́ще Сві́та, непреста́нноє Тебі́ іспові́даніє і благодаре́ніє возсила́єм, Безнача́льному Отцю́ со Єдиноро́дним Твої́м Си́ном і Всесвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом ни́ні, і при́сно, і во ві́ки віко́в, амі́нь.","І а́ще у́бо Бог Госпо́дь: Пі́то єсть, ізобрази́тельная глаго́лем зді. А́ще же Аллилу́я, промовляй їх по дев’ятому часі, а дев’ятий час по шостому починається так: Прийді́те, поклоні́мся: Три́жди. І псалми́, і про́чая.","Знай, що на Святій Афонській горі й в інших монастирях на годинах завжди замість кондака промовляють по черзі ці встановлені тропарі, тобто: Благослове́н єси́, Христе́ Бо́же наш: І про́чая.","§А кондак промовляють лише на зображальних, окрім Владичніх празників і святих, коли співають полієлей і велике славослов’я: тоді кондак промовляють усюди."]}],"notes":[]},{"u":"Міжчасся шостого часу","e":"Interval after the Sixth Hour","secs":[{"ps":["Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему.","§І псалми."]},{"h":"Псалом 55","ps":["Поми́луй м'я, Бо́же, я́ко попра́ м'я челові́к, весь день боря́ стужи́ мі. Попра́ша м'я вразі́ мої́ весь день, я́ко мно́зі борю́щії м'я с висоти́. В день не убою́ся, аз же упова́ю на Тя. О Бо́зі похвалю́ словеса́ моя́, на Бо́га упова́х, не убою́ся, что сотвори́ть мні плоть? Весь день слове́с мої́х гнуша́хуся, на м'я вся помишле́нія їх на зло. Вселя́ться і скри́ють, ті́ї п'я́ту мою́ сохраня́ть, я́коже потерпі́ша ду́шу мою́. Ні о чесо́мже отри́неши я, гні́вом лю́ди низведе́ши. Бо́же, живо́т мой возвісти́х Тебі́, положи́л єси́ сле́зи моя́ пред Тобо́ю, я́ко і во обітова́нії Твоє́м. Да возвратя́ться вразі́ мої́ всп'ять, во́ньже а́ще день призову́ Тя, се позна́х, я́ко Бог мой єси́ Ти. О Бо́зі похвалю́ глаго́л, о Го́споді похвалю́ сло́во. На Бо́га упова́х, не убою́ся, что сотвори́ть мні челові́к? Во мні, Бо́же, моли́тви, я́же возда́м хвали́ Твоєя́, я́ко ізба́вил єси́ ду́шу мою́ от сме́рти, о́чі мої́ от слез, і но́зі мої́ от поползнове́нія, благоугожду́ пред Го́сподем во сві́ті живи́х."]},{"h":"Псалом 56","ps":["Поми́луй м'я, Бо́же, поми́луй м'я, я́ко на Тя упова́ душа́ моя́, і на сінь крилу́ Твоє́ю наді́юся, до́ндеже пре́йдеть беззако́ніє. Воззову́ к Бо́гу Ви́шнему, Бо́гу, благоді́явшему мні. Посла́ с Небесе́ і спасе́ м'я, даде́ в поноше́ніє попира́ющия м'я, посла́ Бог ми́лость Свою́ і і́стину Свою́, і ізба́ви ду́шу мою́ от среди́ ски́мнов. Поспа́х смуще́н, си́нове челові́честії, зу́би їх ору́жія і стрі́ли, і язи́к їх меч остр. Вознеси́ся на Небеса́, Бо́же, і по всей землі́ сла́ва Твоя́. Сіть угото́ваша нога́м мої́м і сляко́ша ду́шу мою́, іскопа́ша пред лице́м мої́м я́му і впадо́ша в ню. Гото́во се́рдце моє́, Бо́же, гото́во се́рдце моє́, воспою́ і пою́ во сла́ві моє́й. Воста́ни сла́ва моя́, воста́ни псалти́рю і гу́слі, воста́ну ра́но. Іспові́мся Тебі́ в лю́діх, Го́споди, воспою́ Тебі́ во язи́ціх, я́ко возвели́чися до Небе́с ми́лость Твоя́, і да́же до о́блак і́стина Твоя́. Вознеси́ся на Небеса́, Бо́же, і по всей землі́ сла́ва Твоя́."]},{"h":"Псалом 69","ps":["Бо́же, в по́мощ мою́ воньми́, Го́споди, помощі́ мі потщи́ся. Да постидя́ться і посра́м'яться і́щущії ду́шу мою́, да возвратя́ться всп'ять і постидя́ться хотя́щії мі зла́я. Да возвратя́ться а́біє стидя́щеся глаго́лющії мі: бла́гоже, бла́гоже. Да возра́дуються і возвеселя́ться о Тебі́ всі і́щущії Тебі́, Бо́же, і да глаго́лють ви́ну, да возвели́читься Госпо́дь, лю́б'ящії спасе́ніє Твоє́: аз же нищ єсьм і убо́г, Бо́же, помози́ мі: Помо́щник мой і Ізба́витель мой єси́ Ти, Го́споди, не закосни́.","Сла́ва, і ни́ні: Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь."]},{"h":"Ці тропарі, глас 1","ps":["Спаси́, Го́споди, лю́ди Твоя́ / і благослови́ достоя́ніє Твоє́, / побі́ди на сопроти́вния да́руя / і Твоє́ сохраня́я Кресто́м Твої́м жи́тельство.","Слава: Болі́зньми святи́х, ї́миже о Тебі́ пострада́ша, / умоле́н бу́ди, Го́споди, / і вся на́ша болі́зні ісціли́, / Человіколю́бче, мо́лимся.","І нині: Моли́твами, Го́споди, / всіх святи́х і Богоро́диці, / Твой мир даждь нам, / і поми́луй нас, я́ко Єди́н щедр.","Го́споди поми́луй, 40. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Моли́твами святи́х оте́ць на́ших, Го́споди, Ісу́се Христе́, Бо́же наш, поми́луй нас. І ми: Амі́нь."]},{"h":"Потім три великі поклони, промовляючи на кожному поклоні молитву прп. Єфрема","ps":["Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н."]},{"h":"І молитва святого Василія Великого","ps":["Бо́же і Го́споди сил і всея́ тва́рі Соді́телю, І́же за милосе́рдіє безприкла́дния ми́лости Твоєя́ Єдиноро́днаго Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, низпосла́вий на спасе́ніє ро́да на́шего, і честни́м Єго́ Кресто́м рукописа́ніє гріх на́ших растерза́вий, і побіди́вий тім нача́ла і вла́сті тьми. Сам, Влади́ко Человіколю́бче, прийми́ і нас, грі́шних, благода́рственния сія́ і моле́бния моли́тви і ізба́ви нас от вся́каго всегуби́тельнаго і мра́чнаго прегріше́нія і всіх озло́бити нас і́щущих ви́димих і неви́димих враг. Пригвозди́ стра́ху Твоєму́ пло́ті на́ша і не уклони́ серде́ць на́ших в словеса́ іли́ помишле́нія лука́вствія, но любо́вію Твоє́ю уязви́ ду́ші на́ша, да, к Тебі́ всегда́ взира́юще і є́же от Тебе́ сві́том наставля́ємі, Тебі́, непристу́пнаго і присносу́щнаго зря́ще Сві́та, непреста́нноє Тебі́ іспові́даніє і благодаре́ніє возсила́єм, Безнача́льному Отцю́ со Єдиноро́дним Твої́м Си́ном і Всесвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом ни́ні, і при́сно, і во ві́ки віко́в, амі́нь.","І а́ще у́бо Бог Госпо́дь Пі́то єсть, ізобрази́тельная глаго́лем зді. А́ще же Аллилу́я, Глаго́ли я по дев'я́том часі́.","А дев'я́тий час по шесто́м начина́ється си́це: Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь. Го́споди поми́луй, 12. Сла́ва, і ни́ні: Прийді́те, поклоні́мся: Три́жди: І псалми́, і про́чая."]}],"notes":[]},{"u":"Зображальні","e":"Typica (Izobrazitelny)","secs":[{"ps":["Глаго́ли си́це: Благослови́, душе́ моя́, Го́спода, благослове́н єси́ Го́споди."]},{"h":"Псалом 102","ps":["Благослови́, душе́ моя́, Го́спода, і вся вну́тренняя моя́ і́м'я свя́тоє Єго́. Благослови́, душе́ моя́, Го́спода, і не забива́й всіх воздая́ній Єго́, очища́ющаго вся беззако́нія твоя́, ісціля́ющаго вся неду́ги твоя́, ізбавля́ющаго от істлі́нія живо́т твой, вінча́ющаго тя ми́лостію і щедро́тами, ісполня́ющаго во благи́х жела́ніє твоє́: обнови́ться я́ко о́рля ю́ность твоя́. Творя́й ми́лостині Госпо́дь, і судьбу́ всім оби́димим. Сказа́ путі́ Своя́ Моїсе́йові, синово́м Ізра́їлевим хоті́нія Своя́: Щедр і Ми́лостив Госпо́дь, Долготерпіли́в і Многоми́лостив. Не до конця́ прогні́вається, ніже́ во вік вражду́єть, не по беззако́нієм на́шим сотвори́л єсть нам, ніже́ по гріхо́м на́шим возда́л єсть нам. Я́ко по висоті́ небе́сній от землі́, утверди́л єсть Госпо́дь ми́лость Свою́ на боя́щихся Єго́. Єли́ко отстоя́ть восто́ці от за́пад, уда́лил єсть от нас беззако́нія на́ша. Я́коже ще́дрить оте́ць си́ни, уще́дри Госпо́дь боя́щихся Єго́. Я́ко Той позна́ созда́ніє на́ше, пом'яну́, я́ко персть єсьми́. Челові́к, я́ко трава́ дні́є єго́, я́ко цвіт се́льний, та́ко оцвіте́ть, я́ко дух про́йде в нем, і не бу́деть, і не позна́єть ктому́ мі́ста своєго́. Ми́лость же Госпо́дня от ві́ка і до ві́ка на боя́щихся Єго́, і пра́вда Єго́ на сині́х сино́в, храня́щих заві́т Єго́, і по́мнящих за́повіді Єго́ твори́ти я. Госпо́дь на Небесі́ угото́ва Престо́л Свой, і Ца́рство Єго́ всі́ми облада́єть. Благослові́те Го́спода всі А́нгели Єго́, си́льнії крі́постію, творя́щії сло́во Єго́, усли́шати глас слове́с Єго́. Благослові́те Го́спода вся Си́ли Єго́, слуги́ Єго́, творя́щії во́лю Єго́. Благослові́те Го́спода вся діла́ Єго́, на вся́ком мі́сті влади́чества Єго́.","Сла́ва, Пе́рвий лик ви́шшим гла́сом. І ни́ні, Втори́й лик.","Па́ки пе́рвий лик: Благослови́, душе́ моя́, Го́спода, і вся вну́тренняя моя́ і́м'я свя́тоє Єго́. Благослове́н єси́, Го́споди.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху."]},{"h":"Псалом 145","ps":["Хвали́, душе́ моя́, Го́спода. Восхвалю́ Го́спода в животі́ моє́м, пою́ Бо́гу моєму́, до́ндеже єсьм. Не наді́йтеся на кня́зі, на си́ни челові́чеськія, в ни́хже ність спасе́нія. Ізи́деть дух єго́ і возврати́ться в зе́млю свою́. В той день поги́бнуть вся помишле́нія єго́. Блаже́н, єму́же Бог Іа́ковль Помо́щник єго́, упова́ніє єго́ на Го́спода Бо́га своєго́, сотво́ршаго не́бо і зе́млю, мо́ре і вся, я́же в них, храня́щаго і́стину во вік, творя́щаго суд оби́димим, даю́щаго пи́щу а́лчущим. Госпо́дь ріши́ть окова́нния. Госпо́дь умудря́єть сліпці́. Госпо́дь возво́дить низве́рженния. Госпо́дь лю́бить пра́ведники. Госпо́дь храни́ть прише́льці, си́ра і вдову́ при́йметь і путь грі́шних погуби́ть. Воцари́ться Госпо́дь во вік, Бог твой, Сіо́не, в род і род.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Єдиноро́дний Си́не і Сло́ве Бо́жий, Безсме́ртен Сий / і ізво́ливий спасе́нія на́шего ра́ди / воплоти́тися от Святи́я Богоро́диці і Присноді́ви Марі́ї, / непрело́жно вочелові́чивийся, / распни́йся же, Христе́ Бо́же, сме́ртію смерть попра́вий, / Єди́н Сий Святи́я Тро́йці, / спрославля́ємий Отцю́ і Свято́му Ду́ху, спаси́ нас.","Влади́ко Го́споди Ісу́се Христе́, Бо́же наш: Поє́м Пом'яни́ нас, Го́споди: з солодкоспівом, глас 8. І відразу Блаже́нні ни́щії ду́хом: По закінченні ж стихів, коли обидва хори з’єдналися, промовляють так: Пом'яни́ нас, Го́споди: Возгла́сно.","Во Ца́рствії Твоє́м пом'яни́ нас, Го́споди, єгда́ при́йдеши, во Ца́рствії Твоє́м.","Блаже́нні ни́щії ду́хом, я́ко тіх єсть Ца́рство Небе́сноє.","Блаже́нні пла́чущії, я́ко ті́ї уті́шаться.","Блаже́нні кро́тції, я́ко ті́ї наслі́дять зе́млю.","Блаже́нні а́лчущії і жа́ждущії пра́вди, я́ко ті́ї наси́тяться.","Блаже́нні ми́лостивії, я́ко ті́ї поми́ловані бу́дуть.","Блаже́нні чи́стії се́рдцем, я́ко ті́ї Бо́га у́зрять.","Блаже́нні миротво́рці, я́ко ті́ї си́нове Бо́жії нареку́ться.","Блаже́нні ізгна́ні пра́вди ра́ди, я́ко тіх єсть Ца́рство Небе́сноє.","Блаже́нні єсте́, єгда́ поно́сять вам, і ізжену́ть, і реку́ть всяк зол глаго́л на ви, лжу́ще Мене́ ра́ди.","Ра́дуйтеся і веселі́теся, я́ко мзда ва́ша мно́га на Небесі́х.","Якщо ж Великий піст, обидва хори, з’єднавшись, співають із солодкоспівом: Пом'яни́ нас, Го́споди: І покло́н єди́н на єди́но ко́єждо. А́ще же ні, ско́ро. Сла́ва, і ни́ні: Пом'яни́ нас, Го́споди:","§Якщо немає Літургії, читаємо Апостол і Євангеліє."]},{"h":"Прокімни дня. У понеділок, глас 4","ps":["Творя́й А́нгели Своя́ ду́хи / і слуги́ Своя́ пла́мень о́гненний.","Стих: Благослови́, душе́ моя́, Го́спода, Го́споди Бо́же мой, возвели́чился єси́ зіло́."]},{"h":"У вівторок, глас 7","ps":["Возвесели́ться пра́ведник о Го́споді, / і упова́єть на Него́.","Стих: Усли́ши Бо́же глас мой, внегда́ моли́ти мі ся к Тебі́."]},{"h":"У середу, глас 3","ps":["Вели́чить душа́ Моя́ Го́спода, / і возра́довася дух Мой о Бо́зі Спа́сі Моє́м.","Стих: Я́ко призрі́ на смире́ніє Раби́ Своєя́, се бо, отни́ні ублажа́ть М'я всі ро́ди."]},{"h":"У четвер, глас 8","ps":["Во всю зе́млю ізи́де віща́ніє їх / і в конці́ вселе́нния глаго́ли їх.","Стих: Небеса́ пові́дають сла́ву Бо́жию, / творе́ніє же руку́ Єго́ возвіща́єть твердь."]},{"h":"У п’ятницю, глас 7","ps":["Возносі́те Го́спода Бо́га на́шего / і поклоня́йтеся подно́жію но́гу Єго́, я́ко свя́то єсть.","Стих: Госпо́дь воцари́ся, да гні́ваються лю́діє."]},{"h":"У суботу, глас 8","ps":["Веселі́теся о Го́споді, / і ра́дуйтеся пра́веднії.","Стих: Блаже́нні, ї́хже оста́вишася беззако́нія і ї́хже прикри́шася гріси́.","Пом'яни́ нас, Го́споди, єгда́ при́йдеши, во Ца́рствії Твоє́м.","Пом'яни́ нас, Влади́ко, єгда́ при́йдеши, во Ца́рствії Твоє́м.","Пом'яни́ нас, Святи́й, єгда́ при́йдеши, во Ца́рствії Твоє́м.","Лик Небе́сний поє́ть Тя і глаго́леть: Свят, Свят, Свят Госпо́дь Савао́ф, іспо́лнь Не́бо і земля́ сла́ви Твоєя́.","Стих: Приступі́те к Нему́ і просвіті́теся, і ли́ця ва́ша не постидя́ться.","Лик Небе́сний поє́ть Тя і глаго́леть: Свят, Свят, Свят Госпо́дь Савао́ф, іспо́лнь Не́бо і земля́ сла́ви Твоєя́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Лик святи́х А́нгел і Арха́нгел со всі́ми Небе́сними си́лами поє́ть Тя і глаго́леть: Свят, Свят, Свят Госпо́дь Савао́ф, іспо́лнь Не́бо і земля́ сла́ви Твоєя́."]},{"h":"Якщо немає Літургії","ps":["І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Ві́рую во єди́наго Бо́га Отця́ Вседержи́теля, Творця́ не́бу і землі́, ви́димим же всім і неви́димим. І во єди́наго Го́спода Ісу́са Христа́, Си́на Бо́жия, Єдиноро́днаго, І́же от Отця́ рожде́ннаго пре́жде всіх вік. Сві́та от Сві́та, Бо́га і́стинна от Бо́га і́стинна, рожде́нна, несотворе́нна, єдиносу́щна Отцю́, І́мже вся би́ша. Нас ра́ди челові́к і на́шего ра́ди спасе́нія сше́дшаго с небе́с і воплоти́вшагося от Ду́ха Свя́та і Марі́ї Ді́ви і вочелові́чшася. Расп'я́таго же за ни при Понті́йстім Пила́ті, і страда́вша, і погребе́нна. І воскре́сшаго в тре́тій день по Писа́нієм. І возше́дшаго на Небеса́, і сідя́ща одесну́ю Отця́. І па́ки гряду́щаго со сла́вою суди́ти живи́м і ме́ртвим, Єго́же Ца́рствію не бу́деть конця́. І в Ду́ха Свята́го, Го́спода, Животворя́щаго, І́же от Отця́ ісходя́щаго, І́же со Отце́м і Си́ном спокланя́єма і ссла́вима, глаго́лавшаго проро́ки. Во єди́ну Святу́ю, Собо́рную і Апо́стольськую Це́рков. Іспові́дую єди́но креще́ніє во оставле́ніє гріхо́в. Ча́ю воскресе́нія ме́ртвих, і жи́зні бу́дущаго ві́ка. Амі́нь.","Осла́би, оста́ви, прости́, Бо́же, прегріше́нія на́ша, во́льная і нево́льная, / я́же в сло́ві і в ді́лі, / я́же во ві́дінії і не во ві́дінії, / я́же во дні і в нощі́, / я́же во умі́ і в помишле́нії, / вся нам прости́, я́ко Благ і Человіколю́бець.","О́тче наш, І́же єси́ на Небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на Небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь.","§Якщо ж Владичній празник, промовляємо його кондак.","Якщо ж у цей день трапиться й пам’ять святого, що її святкують, спершу промовляється кондак святого. Сла́ва, і ни́ні, Пра́здника. А́ще же Аллилу́я співається, або немає Владичнього празника, ані святого, що його святкують, промовляй спершу кондак Преображення, потім (у середу й п’ятницю — Хресту) дня й храму. Якщо ж храм Господній, промовляй спершу кондак храму, потім дня й святого за порядком.","Сла́ва: Со святи́ми упоко́й, Христе́:","І ни́ні: Предста́тельство христия́н: або храму Богородиці. У понеділок — Безтілесних, так само у вівторок — Предтечі, і далі за порядком."]},{"h":"Кондак Преображення, глас 7","ps":["На горі́ преобрази́лся єси́, / і я́коже вміща́ху ученици́ Твої́, / сла́ву Твою́, Христе́ Боже́, ви́діша, / да єгда́ Тя у́зрять распина́єма, / страда́ніє у́бо уразумі́ють во́льноє, / ми́рові же пропові́дять, / я́ко Ти єси́ воі́стину О́тчеє сія́ніє."]},{"h":"У понеділок — кондак Безтілесних Сил, глас 2","ps":["Архістрати́зі Бо́жії, служи́теліє Боже́ственния сла́ви, / А́нгелов нача́льници і челові́ков наста́вници, / поле́зноє нам просі́те і ве́лію ми́лость, / я́ко Безпло́тних Архістрати́зі."]},{"h":"У вівторок — кондак Предтечі, глас 2.","ps":["Подо́бен: Ви́шніх іща́:","Проро́че Бо́жий і Предте́че благода́ті, / главу́ твою́, я́ко ши́пок свяще́ннійший от землі́ обрі́тше, / ісціле́нія всегда́ приє́млем, / і́бо па́ки, я́коже пре́жде / в ми́рі пропові́дуєши покая́ніє."]},{"h":"У середу й п’ятницю — кондак Чесному Хресту, глас 4","ps":["Вознеси́йся на Крест во́лею, / тезоімени́тому Твоєму́ но́вому жи́тельству / щедро́ти Твоя́ да́руй, Христе́ Бо́же, / возвесели́ нас си́лою Твоє́ю, / побі́ди дая́ нам на сопоста́ти, / посо́біє іму́щим Твоє́ ору́жіє ми́ра, / непобіди́мую побі́ду."]},{"h":"У четвер — кондак святих апостолів, глас 2","ps":["Тве́рдия і Боговіща́нния пропові́дателі, / верх учени́к Твої́х, Го́споди, / прия́л єси́ в наслажде́ніє благи́х Твої́х і поко́й: / болі́зні бо о́ніх і смерть прия́л єси́ па́че вся́каго всепло́дія, / Єди́не, сві́дий серде́чная."]},{"h":"Того ж дня — кондак святого Миколая, глас 3","ps":["В Ми́ріх, свя́те, священноді́йствитель показа́лся єси́, / Христо́во бо, преподо́бне, Єва́нгеліє іспо́лнив, / положи́л єси́ ду́шу твою́ о лю́діх твої́х / і спасл єси́ непови́нния от сме́рти. / Сего́ ра́ди освяти́лся єси́, / я́ко вели́кий таї́нник Бо́жия благода́ті."]},{"h":"У суботу, коли промовляємо","ps":["Слава, глас 8: Со святи́ми упоко́й / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная."]},{"h":"І цей мученичен","ps":["І нині, глас 8: Я́ко нача́тки єстества́, Насади́телю тва́рі, / вселе́нная прино́сить Ті, Го́споди, богоно́сния му́ченики, / тіх моли́твами в ми́рі глубо́ці / Це́рков Твою́, жи́тельство Твоє́, / Богоро́дицею соблюди́, Многоми́лостиве."]},{"h":"Це промовляється щодня, крім суботи","ps":["Слава, глас 8: Со святи́ми упоко́й / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная.","І нині, глас 6: Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, / предста́тельствующи при́сно, Богоро́дице, чту́щих Тя.","І а́ще єсть Четиредеся́тниця, Го́споди поми́луй, 40. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Бо́же, уще́дри ни і благослови́ ни, просвіти́ лице́ Твоє́ на ни і поми́луй ни.","І ми: Амі́нь.","І (творимо) зазначені 16 поклонів із молитвою святого Єфрема. Коли ж ми підведемося, предстоятель починає вечірню: Прийді́те, поклоні́мся: Три́жди. І предначина́тельний псало́м: Благослови́ душе́ моя́ Го́спода:"]},{"h":"Якщо ж Літургія Передосвячених Дарів","ps":["Трисвято́є. Пресвята́я Тро́йце: По О́тче наш:","Священник: Я́ко Твоє́ єсть Ца́рство:","Ми ж: Амі́нь. Го́споди поми́луй, 12. Всесвята́я Тро́йце:","Священник: Прему́дрость.","Хор: Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, / Присноблаже́нную і Пренепоро́чную і Ма́тер Бо́га на́шего.","Священник: Пресвята́я Богоро́дице, спаси́ нас.","Хор: Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю Тя велича́єм.","Священник: Сла́ва Тебі́, Христе́ Бо́же, упова́ніє на́ше, сла́ва Тебі́.","Хор: Сла́ва, і ни́ні, Го́споди поми́луй, Три́жди. Благослови́.","§І відпуст."]},{"h":"Якщо ж не Великий піст — після кондаків","ps":["Го́споди поми́луй, 12.","І моли́тву: Всесвята́я Тро́йце, Єдиносу́щная Держа́во, Неразді́льноє Ца́рство, всіх благи́х Вина́: благоволи́ же і о мні, грі́шнім, утверди́, вразуми́ се́рдце моє́ і всю мою́ отими́ скве́рну. Просвіти́ мою́ мисль, да ви́ну сла́влю, пою́, і покланя́юся, і глаго́лю: Єди́н Свят, Єди́н Госпо́дь, Ісу́с Христо́с во сла́ву Бо́га Отця́, амі́нь.","Бу́ди і́м'я Госпо́днє благослове́нно от ни́ні і до ві́ка. Три́жди.","Сла́ва, і ни́ні:"]},{"h":"Псалом 33","ps":["Благословлю́ Го́спода на вся́коє вре́м'я, ви́ну хвала́ Єго́ во усті́х мої́х. О Го́споді похва́литься душа́ моя́, да усли́шать кро́тції і возвеселя́ться. Возвели́чіте Го́спода со мно́ю і вознесе́м і́м'я Єго́ вку́пі. Взиска́х Го́спода і усли́ша м'я, і от всіх скорбе́й мої́х ізба́ви м'я. Приступі́те к Нему́ і просвіті́теся, і ли́ця ва́ша не постидя́ться. Сей ни́щий воззва́, і Госпо́дь усли́ша ї, і от всіх скорбе́й єго́ спасе́ ї. Ополчи́ться А́нгел Госпо́день о́крест боя́щихся Єго́, і ізба́вить їх. Вкусі́те і ви́діте, я́ко благ Госпо́дь; блаже́н муж, і́же упова́єть Нань. Бо́йтеся Го́спода, всі святі́ї Єго́, я́ко ність лише́нія боя́щимся Єго́. Бога́тії обнища́ша і взалка́ша, взиска́ющії же Го́спода не лиша́ться вся́каго бла́га. Прийді́те, ча́да, послу́шайте мене́, стра́ху Госпо́дню научу́ вас. Кто єсть челові́ко хотя́й живо́т, люб'я́й дні ви́діти бла́гі? Удержи́ язи́к твой от зла, і устні́ твої́, є́же не глаго́лати льсти. Уклони́ся от зла і сотвори́ бла́го. Взищи́ ми́ра, і пожени́ ї. О́чі Госпо́дні на пра́ведния, і у́ші Єго́ в моли́тву їх. Лице́ же Госпо́днє на творя́щия зла́я, є́же потреби́ти от землі́ па́м'ять їх. Воззва́ша пра́веднії, і Госпо́дь усли́ша їх, і от всіх скорбе́й їх ізба́ви їх. Близ Госпо́дь сокруше́нних се́рдцем, і смире́нния ду́хом спасе́ть. Мно́гі ско́рбі пра́ведним, і от всіх їх ізба́вить я Госпо́дь. Храни́ть Госпо́дь вся ко́сті їх, ні єди́на от них сокруши́ться. Смерть грі́шников люта́, і ненави́дящії пра́веднаго прегрі́шать. Ізба́вить Госпо́дь ду́ші раб Свої́х, і не прегріша́ть всі, упова́ющії на Него́.","І по возгла́сі: Прему́дрость.","Хор: Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, / Присноблаже́нную і Пренепоро́чную і Ма́тер Бо́га на́шего.","Священник: Пресвята́я Богоро́дице, спаси́ нас.","Хор: Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","Священник: Сла́ва Тебі́, Христе́ Бо́же, упова́ніє на́ше, сла́ва Тебі́.","Хор: Сла́ва, і ни́ні, Го́споди поми́луй, Три́жди. Благослови́.","§І звершується відпуст."]}],"notes":[]},{"u":"Девʼятий час","e":"Ninth Hour","secs":[{"ps":["По Благослове́н Бог наш: Ми глаго́лем: Амі́нь.","Сла́ва Тебі́, Бо́же наш, сла́ва Тебі́.","Царю́ Небе́сний, Уті́шителю, Ду́ше і́стини, І́же везді́ сий і вся ісполня́яй, Сокро́вище благи́х і жи́зні Пода́телю, прийди́ і всели́ся в ни, і очи́сти ни от вся́кия скве́рни, і спаси́, Бла́же, ду́ші на́ша.","Святи́й Бо́же, Святи́й Крі́пкий, Святи́й Безсме́ртний, поми́луй нас. Три́жди.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас; Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй, Три́жди. Сла́ва, і ни́ні:","О́тче наш, І́же єси́ на Небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на Небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь.","Потім: Го́споди, поми́луй, 12. Сла́ва, і ни́ні:","Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему."]},{"h":"Потім псалми. Псалом 83","ps":["Коль возлю́бленна селе́нія Твоя́, Го́споди сил! Жела́єть і скончава́ється душа́ моя́ во двори́ Госпо́дні, се́рдце моє́ і плоть моя́ возра́довастася о Бо́зі жи́ві. І́бо пти́ця обрі́те себі́ хра́мину, і го́рлиця гніздо́ себі́, іді́же положи́ть птенці́ своя́, олтари́ Твоя́, Го́споди сил, Царю́ мой і Бо́же мой. Блаже́нні живу́щії в дому́ Твоє́м, во ві́ки віко́во восхва́лять Тя. Блаже́н муж, єму́же єсть заступле́ніє єго́ у Тебе́; восхожде́нія в се́рдці своє́м положи́, во юдо́ль плаче́вную, в мі́сто є́же положи́, і́бо благослове́ніє дасть законополага́яй. По́йдуть от си́ли в си́лу: яви́ться Бог бого́во в Сіо́ні. Го́споди Бо́же сил, усли́ши моли́тву мою́, внуши́, Бо́же Іа́ковль. Защи́тниче наш, виждь, Бо́же, і при́зри на лице́ христа́ Твоєго́. Я́ко лу́чше день єди́н во дво́ріх Твої́х па́че ти́сящ: ізво́лих примета́тися в дому́ Бо́га моєго́ па́че, не́же жи́ти мі в селе́ніїх грі́шничих. Я́ко ми́лость і і́стину лю́бить Госпо́дь, Бог благода́ть і сла́ву дасть, Госпо́дь не лиши́ть благи́х ходя́щих незло́бієм. Го́споди Бо́же сил, Блаже́н челові́к упова́яй на Тя."]},{"h":"Псалом 84","ps":["Благоволи́л єси́, Го́споди, зе́млю Твою́, возврати́л єси́ плін Іа́ковль: оста́вил єси́ беззако́нія люде́й Твої́х, покри́л єси́ вся гріхи́ їх. Укроти́л єси́ весь гнів Твой, возврати́лся єси́ от гні́ва я́рости Твоєя́. Возврати́ нас, Бо́же спасе́ній на́ших, і отврати́ я́рость Твою́ от нас. Єда́ во ві́ки прогні́ваєшися на ни? Іли́ простре́ши гнів Твой от ро́да в род? Бо́же, Ти обра́щся оживи́ши ни, і лю́діє Твої́ возвеселя́ться о Тебі́. Яви́ нам, Го́споди, ми́лость Твою́, і спасе́ніє Твоє́ даждь нам. Усли́шу, что рече́ть о мні Госпо́дь Бог: я́ко рече́ть мир на лю́ди Своя́, і на преподо́бния Своя́, і на обраща́ющия сердця́ к Нему́. Оба́че близ боя́щихся Єго́ спасе́ніє Єго́, всели́ти сла́ву в зе́млю на́шу. Ми́лость і і́стина сріто́стіся, пра́вда і мир облобиза́стася. І́стина от землі́ возсія́, і пра́вда с Небесе́ прини́че, і́бо Госпо́дь дасть бла́гость, і земля́ на́ша дасть плод свой. Пра́вда пред Ним преди́деть, і положи́ть в путь стопи́ своя́."]},{"h":"Псалом 85","ps":["Приклони́, Го́споди, у́хо Твоє́, і усли́ши м'я, я́ко нищ і убо́г єсьм аз. Сохрани́ ду́шу мою́, я́ко преподо́бен єсьм: спаси́ раба́ Твоєго́, Бо́же мой, упова́ющаго на Тя. Поми́луй м'я, Го́споди, я́ко к Тебі́ воззову́ весь день. Возвесели́ ду́шу раба́ Твоєго́, я́ко к Тебі́ взях ду́шу мою́. Я́ко Ти, Го́споди, Благ і Кро́ток, і Многоми́лостив всім призива́ющим Тя. Внуши́, Го́споди, моли́тву мою́, і воньми́ гла́су моле́нія моєго́. В день ско́рби моєя́ воззва́х к Тебі́, я́ко усли́шал м'я єси́. Ність подо́бен Тебі́ в бозі́х, Го́споди, і ність по діло́м Твої́м. Всі язи́ци, єли́ки сотвори́л єси́, при́йдуть і покло́няться пред Тобо́ю, Го́споди, і просла́в'ять і́м'я Твоє́, я́ко Ве́лій єси́ Ти, і творя́й чудеса́, Ти єси́ Бог єди́н. Наста́ви м'я, Го́споди, на путь Твой, і пойду́ во і́стині Твоє́й; да возвесели́ться се́рдце моє́ боя́тися і́мене Твоєго́. Іспові́мся Тебі́, Го́споди Бо́же мой, всім се́рдцем мої́м, і просла́влю і́м'я Твоє́ во вік: я́ко ми́лость Твоя́ ве́лія на мні, і ізба́вил єси́ ду́шу мою́ от а́да преіспо́днійшаго. Бо́же, законопресту́пници воста́ша на м'я, і сонм держа́вних взиска́ша ду́шу мою́, і не предложи́ша Тебі́ пред собо́ю. І Ти, Го́споди Бо́же мой, Ще́дрий і Ми́лостивий, Долготерпіли́вий, і Многоми́лостивий і і́стинний, при́зри на м'я і поми́луй м'я, даждь держа́ву Твою́ о́троку Твоєму́, і спаси́ си́на раби́ Твоєя́. Сотвори́ со мно́ю зна́меніє во бла́го, і да ви́дять ненави́дящії м'я, і постидя́ться, я́ко Ти, Го́споди, помо́гл мі і уті́шил м'я єси́.","І па́ки: Сотвори́ со мно́ю зна́меніє во бла́го, і да ви́дять ненави́дящії м'я, і постидя́ться, я́ко Ти, Го́споди, помо́гл мі і уті́шил м'я єси́.","Сла́ва, і ни́ні: Аллилу́я, Три́жди. Го́споди, поми́луй, Три́жди.","І а́ще у́бо Бог Госпо́дь, Пі́то, глаго́лем дне тропа́р."]},{"h":"Якщо ж «Алилуя» — цей, глас 8","ps":["І́же в дев'я́тий час / нас ра́ди пло́тію смерть вкуси́вий, / умертви́ пло́ті на́шея мудрова́ніє, / Христе́ Бо́же, і спаси́ нас.","Стих 1: Да прибли́житься моле́ніє моє́ пред Тя, Го́споди, по словесі́ Твоєму́ вразуми́ м'я.","Стих 2: Да вни́деть проше́ніє моє́ пред Тя, Го́споди, по словесі́ Твоєму́ ізба́ви м'я.","§Слава, і нині, Богородичен:","І́же нас ра́ди рожде́йся от Ді́ви / і расп'я́тіє претерпі́в, Благи́й, / іспрове́ргий сме́ртію смерть і воскресе́ніє явле́й я́ко Бог, / не пре́зри, я́же созда́л єси́ руко́ю Твоє́ю. / Яви́ человіколю́біє Твоє́, Ми́лостиве. / Прийми́ ро́ждшую Тя Богоро́дицю, моля́щуюся за ни. / І спаси́, Спа́се наш, лю́ди отча́янния.","Не преда́ждь нас до конця́ І́мене Твоєго́ ра́ди, / і не разори́ заві́та Твоєго́, / і не отста́ви ми́лости Твоєя́ от нас / Авраа́ма ра́ди, возлю́бленнаго от Тебе́, / і за Ісаа́ка, раба́ Твоєго́, / і Ізра́їля, свята́го Твоєго́.","Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь.","§Якщо ж празник, промовляй його кондак."]},{"h":"Якщо ж піст, промовляємо ці тропарі, глас 8","ps":["Ви́дя разбо́йник / Нача́льника Жи́зні на Кресті́ ви́сяща, глаго́лаше: / а́ще не би Бог бил вопло́щся, І́же с на́ми распни́йся, / не би со́лнце лучи́ своя́ потаї́ло, / ніже́ би земля́ трепе́щущи трясла́ся. / Но вся терп'я́й, пом'яни́ м'я, Го́споди, во Ца́рствії Твоє́м.","Слава: Посреді́ двою́ разбо́йнику, / мі́рило пра́ведноє обрі́теся крест Твой: / о́вому у́бо низводи́му во ад тягото́ю хуле́нія, / друго́му же легча́щуся от прегріше́ній к позна́нію Богосло́вія. / Христе́ Бо́же, сла́ва Тебі́.","І нині: А́гнця, і Па́стиря, і Спа́са ми́ра, / на кресті́ зря́щи Ро́ждшая Тя, / глаго́лаше слезя́щи: / мир у́бо ра́дується, приє́мля ізбавле́ніє, / утро́ба же Моя́ гори́ть, зря́щи Твоє́ расп'я́тіє, / є́же за всіх терпи́ши, / Си́не і Бо́же мой.","Го́споди, поми́луй, 40.","І́же на вся́коє вре́м'я і на вся́кий час, на Небесі́ і на землі́, покланя́ємий і сла́вимий, Христе́ Бо́же, Долготерпіли́ве, Многоми́лостиве, Многоблагоутро́бне, І́же пра́ведния люб'я́й і грі́шния ми́луяй, І́же вся зови́й ко спасе́нію обіща́нія ра́ди бу́дущих благ. Сам, Го́споди, прийми́ і на́ша в час сей моли́тви і іспра́ви живо́т наш к за́повідем Твої́м, ду́ші на́ша освяти́, тілеса́ очи́сти, помишле́нія іспра́ви, ми́слі очи́сти і ізба́ви нас от вся́кия ско́рби, зол і болі́зней, огради́ нас святи́ми Твої́ми А́нгели, да ополче́нієм їх соблюда́єми і наставля́ємі, дости́гнем в соєдине́ніє ві́ри і в ра́зум непристу́пния Твоєя́ сла́ви, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь.","Го́споди поми́луй, Три́жди. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Бо́же, уще́дри ни і благослови́ ни, просвіти́ лице́ Твоє́ на ни і поми́луй ни.","§Якщо ж Різдвяний піст або піст святих апостолів, то замість співу міжчасся — зазначені 16 поклонів. На святий же Великий піст належить творити лише три великі поклони.","Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н."]},{"h":"Якщо ж ні — після вигуку ця молитва святого Василія Великого","ps":["Влади́ко Го́споди, Ісу́се Христе́, Бо́же наш, долготерпі́вий о на́ших согріше́ніїх і да́же до ни́нішняго часа́ приведи́й нас, во́ньже, на Животворя́щем Дре́ві ви́ся, благоразу́мному разбо́йнику і́же в рай путесотвори́л єси́ вход і сме́ртію смерть разруши́л єси́: очи́сти нас, грі́шних і недосто́йних раб Твої́х, согріши́хом бо і беззако́нновахом і ні́сми досто́йні возвісти́ очеса́ на́ша і воззрі́ти на висоту́ Небе́сную, зане́ оста́вихом путь пра́вди Твоєя́ і ходи́хом во во́лях серде́ць на́ших. Но мо́лим Твою́ безмі́рную бла́гость: пощади́ нас, Го́споди, по мно́жеству ми́лости Твоєя́, і спаси́ нас І́мене Твоєго́ ра́ди свята́го, я́ко ісчезо́ша в суєті́ дні́є на́ші, ізми́ нас із руки́ сопроти́внаго, і оста́ви нам гріхи́ на́ша, і умертви́ плотсько́є на́ше мудрова́ніє, да, ве́тхаго отложи́вше челові́ка, в но́ваго облеце́мся і Тебі́ поживе́м, на́шему Влади́ці і Благоді́телю. І та́ко, Твої́м послі́дующе повелі́нієм, во ві́чний поко́й дости́гнем, іді́же єсть всіх веселя́щихся жили́ще. Ти бо єси́ воі́стину і́стинноє весе́ліє і ра́дость лю́б'ящих Тя, Христе́ Бо́же наш, і Тебі́ сла́ву возсила́єм со Безнача́льним Твої́м Отце́м, і Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь.","§І починаємо вечірню або, якщо піст, Зображальні.","§Знай, що на Афонській горі й в інших монастирях дев’ятий час промовляють у притворі."]}],"notes":[]},{"u":"Міжчасся девʼятого часу","e":"Interval after the Ninth Hour","secs":[{"ps":["Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему.","§І псалми."]},{"h":"Псалом 112","ps":["Хвалі́те, о́троци, Го́спода, хвалі́те і́м'я Госпо́днє. Бу́ди і́м'я Госпо́днє благослове́нно отни́ні і до ві́ка. От восто́к со́лнця до за́пад хва́льно і́м'я Госпо́днє. Висо́к над всі́ми язи́ки Госпо́дь: над небеси́ сла́ва Єго́. Кто я́ко Госпо́дь Бог наш? На висо́ких живи́й і на смире́нния призира́яй на небесі́ і на землі́, воздвиза́яй от землі́ ни́ща і от гно́їща возвиша́яй убо́га, посади́ти єго́ с кня́зі, с кня́зі люде́й свої́х, вселя́я непло́дов в дом ма́тер о ча́діх веселя́щуся."]},{"h":"Псалом 137","ps":["Іспові́мся Тебі́, Го́споди, всім се́рдцем мої́м, і пред А́нгели воспою́ Тебі́, я́ко усли́шал єси́ вся глаго́ли уст мої́х. Поклоню́ся ко хра́му свято́му Твоєму́ і іспові́мся і́мені Твоєму́ о ми́лості Твоє́й і і́стині Твоє́й, я́ко возвели́чил єси́ над всім і́м'я Твоє́ свято́є. Во́ньже а́ще день призову́ Тя, ско́ро усли́ши м'я: умно́жиши м'я в душі́ моє́й си́лою Твоє́ю. Да іспові́дяться Тебі́, Го́споди, всі ца́ріє зе́мстії, я́ко усли́шаша вся глаго́ли уст Твої́х, і да воспою́ть в путеіх Госпо́дніх, я́ко ве́лія сла́ва Госпо́дня, я́ко Висо́ко Госпо́дь, і смире́нния призира́єть, і висо́кая іздале́ча вість. А́ще пойду́ посреді́ ско́рби, живи́ши м'я, на гнів враг мої́х просте́рл єси́ руку́ Твою́, і спасе́ м'я десни́ця Твоя́. Госпо́дь возда́сть за м'я. Го́споди, ми́лость Твоя́ во вік, діл руку́ Твоє́ю не пре́зри."]},{"h":"Псалом 139","ps":["Ізми́ м'я, Го́споди, от челові́ка лука́ва, от му́жа непра́ведна ізба́ви м'я, і́же поми́слиша непра́вду в се́рдці, весь день ополча́ху бра́ні, ізостри́ша язи́к свой, я́ко змії́н, яд а́спидов под устна́ми їх. Сохрани́ м'я, Го́споди, із руки́ грі́шничі, от челові́к непра́ведних ізми́ м'я, і́же поми́слиша зап'я́ти стопи́ моя́. Скри́ша го́рдії сіть мні, і у́жи преп'я́ша сіть нога́ма мої́ма. При стезі́ собла́зни положи́ша мі. Ріх Го́сподеві: Бог мой єси́ Ти, внуши́, Го́споди, глас моле́нія моєго́. Го́споди, Го́споди, си́ло спасе́нія моєго́, осіни́л єси́ над главо́ю моє́ю в день бра́ні. Не преда́ждь мене́, Го́споди, от жела́нія моєго́ грі́шнику: поми́слиша на м'я, не оста́ви мене́, да не когда́ вознесу́ться. Глава́ окруже́нія їх, труд усте́н їх покри́єть я. Паду́ть на них у́глія о́гненная, низложи́ши я в страстеіх, і не постоя́ть. Муж язи́чен не іспра́виться на землі́: му́жа непра́ведна зла́я улов'я́ть во істлі́ніє. Позна́х, я́ко сотвори́ть Госпо́дь суд ни́щим і месть убо́гим. Оба́че пра́веднії іспові́дяться і́мені Твоєму́, і вселя́ться пра́вії с лице́м Твої́м.","Сла́ва, і ни́ні: Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь."]},{"h":"Ці тропарі, глас 8","ps":["Просвіти́вий земни́я Кресто́м, / і призва́вий в покая́ніє грі́шния, / да не отлучи́ши мене́ ста́да Твоєго́, Па́стирю до́брий, / но взищи́ м'я, Влади́ко, заблу́ждшаго, / і свято́му ста́ду Твоєму́ сопричти́, / я́ко Єди́н Ми́лостив і Человіколю́бець.","Слава: Я́ко разбо́йник іспові́даяйся вопію́ Ті, Бла́же: / во Ца́рствії Твоє́м пом'яни́ м'я, Го́споди, і с ним м'я сочета́й, / во́лею страда́ти о нас ізво́ливий.","І нині: Нас ра́ди Расп'я́таго / прийді́те всі воспої́м, / Того́ бо ви́ді Марі́я на дре́ві, і глаго́лаше: / а́ще і расп'я́тіє терпи́ши, / Ти єси́ Син і Бог Мой.","Го́споди, поми́луй, 40. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Моли́твами святи́х оте́ць на́ших, Го́споди, Ісу́се Христе́, Бо́же наш, поми́луй нас.","І ми: Амі́нь."]},{"h":"Потім три великі поклони, промовляючи на кожному поклоні молитву прп. Єфрема","ps":["Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія, і праздносло́вія не даждь мі. Покло́н вели́кий.","Дух же цілому́дрія, смиренному́дрія, терпі́нія, і любве́, да́руй мі рабу́ Твоєму́. Покло́н вели́кий.","Єй, Го́споди Царю́, да́руй мі зрі́ти моя́ прегріше́нія, і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь. Покло́н вели́кий.","Потім 12 малих поклонів, промовляючи собі потай на кожному поклоні: Бо́же, очи́сти м'я, грі́шнаго.","І па́ки, сконча́в покло́ни, глаго́лем моли́тву всю вишепи́санную: Го́споди і Влади́ко живота́ моєго́: І покло́н єди́н вели́кий."]},{"h":"Потім молитва святого Василія Великого","ps":["Влади́ко Го́споди, Ісу́се Христе́, Бо́же наш, долготерпі́вий о на́ших согріше́ніїх і да́же до ни́нішняго часа́ приведи́й нас, во́ньже, на Животворя́щем Дре́ві ви́ся, благоразу́мному разбо́йнику і́же в рай путесотвори́л єси́ вход і сме́ртію смерть разруши́л єси́: очи́сти нас, грі́шних і недосто́йних раб Твої́х, согріши́хом бо і беззако́нновахом і ні́сми досто́йні возвісти́ очеса́ на́ша і воззрі́ти на висоту́ Небе́сную, зане́ оста́вихом путь пра́вди Твоєя́ і ходи́хом во во́лях серде́ць на́ших. Но мо́лим Твою́ безмі́рную бла́гость: пощади́ нас, Го́споди, по мно́жеству ми́лости Твоєя́, і спаси́ нас І́мене Твоєго́ ра́ди свята́го, я́ко ісчезо́ша в суєті́ дні́є на́ші, ізми́ нас із руки́ сопроти́внаго, і оста́ви нам гріхи́ на́ша, і умертви́ плотсько́є на́ше мудрова́ніє, да, ве́тхаго отложи́вше челові́ка, в но́ваго облеце́мся і Тебі́ поживе́м, на́шему Влади́ці і Благоді́телю. І та́ко, Твої́м послі́дующе повелі́нієм, во ві́чний поко́й дости́гнем, іді́же єсть всіх веселя́щихся жили́ще. Ти бо єси́ воі́стину і́стинноє весе́ліє і ра́дость лю́б'ящих Тя, Христе́ Бо́же наш, і Тебі́ сла́ву возсила́єм со Безнача́льним Твої́м Отце́м, і Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь.","Хор: Сла́ва, і ни́ні: Го́споди, поми́луй, Три́жди. Благослови́.","§І відпуст."]}],"notes":[]},{"u":"Мале повечірʼя","e":"Small Compline","secs":[{"ps":["Глаго́леть свяще́нник: Благослове́н Бог наш всегда́, ни́ні і при́сно, і во ві́ки віко́в.","І начина́ють бра́тія: Амі́нь.","Сла́ва Тебі́, Бо́же наш, сла́ва Тебі́.","Царю́ Небе́сний, Уті́шителю, Ду́ше і́стини, І́же везді́ сий і вся ісполня́яй, Сокро́вище благи́х і жи́зні Пода́телю, прийди́ і всели́ся в ни, і очи́сти ни от вся́кия скве́рни, і спаси́, Бла́же, ду́ші на́ша.","Святи́й Бо́же, Святи́й Крі́пкий, Святи́й Безсме́ртний, поми́луй нас. Три́жди.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас; Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй, Три́жди. Сла́ва, і ни́ні:","О́тче наш, І́же єси́ на Небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на Небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","Священник: Я́ко Твоє́ єсть Ца́рство:","І ми: Амі́нь. Го́споди поми́луй, 12.","Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему."]},{"h":"Потім псалом 50","ps":["Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́. Найпа́че оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я; я́ко беззако́ніє моє́ аз зна́ю, і гріх мой предо мно́ю єсть ви́ну. Тебі́ Єди́ному согріши́х і лука́воє пред Тобо́ю сотвори́х, я́ко да оправди́шися во словесі́х Твої́х, і побіди́ши внегда́ суди́ти Ті. Се бо, в беззако́ніїх зача́т єсьм, і во грісі́х роди́ м'я ма́ти моя́. Се бо, і́стину возлюби́л єси́; безві́стная і та́йная прему́дрости Твоєя́ яви́л мі єси́. Окропи́ши м'я іссо́пом, і очи́щуся; оми́єши м'я, і па́че сні́га убілю́ся. Слу́ху моєму́ да́си ра́дость і весе́ліє; возра́дуються ко́сті смире́нния. Отврати́ лице́ Твоє́ от гріх мої́х і вся беззако́нія моя́ очи́сти. Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й. Не отве́ржи мене́ от лиця́ Твоєго́ і Ду́ха Твоєго́ Свята́го не отими́ от мене́. Возда́ждь мі ра́дость спасе́нія Твоєго́ і Ду́хом Влади́чним утверди́ м'я. Научу́ беззако́нния путе́м Твої́м, і нечести́вії к Тебі́ обратя́ться. Ізба́ви м'я от крове́й, Бо́же, Бо́же спасе́нія моєго́; возра́дується язи́к мой пра́вді Твоє́й. Го́споди, устні́ мої́ отве́рзеши, і уста́ моя́ возвістя́ть хвалу́ Твою́. Я́ко а́ще би восхоті́л єси́ же́ртви, дал бих у́бо: всесожже́нія не благоволи́ши. Же́ртва Бо́гу дух сокруше́н; се́рдце сокруше́нно і смире́нно Бог не унічижи́ть. Ублажи́, Го́споди, благоволе́нієм Твої́м Сіо́на, і да сози́ждуться сті́ни Ієрусали́мськія. Тогда́ благоволи́ши же́ртву пра́вди, возноше́ніє і всесожега́ємая; тогда́ возложа́ть на олта́р Твой тельці́."]},{"h":"Псалом 69","ps":["Бо́же, в по́мощ мою́ воньми́, Го́споди, помощі́ мі потщи́ся. Да постидя́ться і посра́м'яться і́щущії ду́шу мою́, да возвратя́ться всп'ять і постидя́ться хотя́щії мі зла́я. Да возвратя́ться а́біє стидя́щеся глаго́лющії мі: бла́гоже, бла́гоже. Да возра́дуються і возвеселя́ться о Тебі́ всі і́щущії Тебі́, Бо́же, і да глаго́лють ви́ну, да возвели́читься Госпо́дь, лю́б'ящії спасе́ніє Твоє́: аз же нищ єсьм і убо́г, Бо́же, помози́ мі: Помо́щник мой і Ізба́витель мой єси́ Ти, Го́споди, не закосни́."]},{"h":"Псалом 142","ps":["Го́споди, усли́ши моли́тву мою́, внуши́ моле́ніє моє́ во і́стині Твоє́й, усли́ши м'я в пра́вді Твоє́й і не вни́ди в суд с рабо́м Твої́м, я́ко не оправди́ться пред Тобо́ю всяк живи́й. Я́ко погна́ враг ду́шу мою́, смири́л єсть в зе́млю живо́т мой, посади́л м'я єсть в те́мних, я́ко ме́ртвия ві́ка. І уни́ во мні дух мой, во мні см'яте́ся се́рдце моє́. Пом'яну́х дні дре́внія, поучи́хся во всіх ді́ліх Твої́х, в творе́ніїх руку́ Твоє́ю поуча́хся. Возді́х к Тебі́ ру́ці мої́, душа́ моя́, я́ко земля́ безво́дная Тебі́. Ско́ро усли́ши м'я, Го́споди, ісчезе́ дух мой, не отврати́ лиця́ Твоєго́ от мене́, і уподо́блюся низходя́щим в ров. Сли́шану сотвори́ мні зау́тра ми́лость Твою́, я́ко на Тя упова́х. Скажи́ мні, Го́споди, путь во́ньже пойду́, я́ко к Тебі́ взях ду́шу мою́. Ізми́ м'я от враг мої́х, Го́споди, к Тебі́ прибіго́х. Научи́ м'я твори́ти во́лю Твою́, я́ко Ти єси́ Бог мой. Дух Твой Благи́й наста́вить м'я на зе́млю пра́ву. І́мене Твоєго́ ра́ди, Го́споди, живи́ши м'я, пра́вдою Твоє́ю ізведе́ши от печа́лі ду́шу мою́. І ми́лостію Твоє́ю потреби́ши враги́ моя́ і погуби́ши вся стужа́ющия душі́ моє́й, я́ко аз раб Твой єсьм."]},{"h":"Славослов’я щоденне","ps":["Сла́ва во ви́шніх Бо́гу, і на землі́ мир, в челові́ціх благоволе́ніє. Хва́лим Тя, благослови́м Тя, кла́няєм Ті ся, славосло́вим Тя, благодари́м Тя, вели́кия ра́ди сла́ви Твоєя́. Го́споди, Царю́ Небе́сний, Бо́же, О́тче Вседержи́телю, Го́споди Си́не Єдиноро́дний, Ісу́се Христе́, і Святи́й Ду́ше. Го́споди Бо́же, А́гнче Бо́жий, Си́не Оте́чь, взе́мляй гріх ми́ра, поми́луй нас. Взе́мляй гріхи́ ми́ра, прийми́ моли́тву на́шу. Сідя́й одесну́ю Отця́, поми́луй нас. Я́ко Ти єси́ Єди́н Свят; Ти єси́ Єди́н Госпо́дь, Ісу́с Христо́с, в сла́ву Бо́га Отця́, амі́нь.","На вся́ку нощ благословлю́ Тя і восхвалю́ і́м'я Твоє́ во ві́ки, і во вік ві́ка.","Го́споди, прибі́жище бил єси́ нам в род і род. Аз ріх: Го́споди, поми́луй м'я, ісціли́ ду́шу мою́, я́ко согріши́х Тебі́. Го́споди, к Тебі́ прибіго́х, научи́ м'я твори́ти во́лю Твою́, я́ко Ти єси́ Бог мой, я́ко у Тебе́ істо́чник живота́, во сві́ті Твоє́м у́зрим світ. Проба́ви ми́лость Твою́ ві́дущим Тя.","Потім: Сподо́би Го́споди, в нощ сію́ без гріха́ сохрани́тися нам. Благослове́н єси́ Го́споди Бо́же оте́ць на́ших, і хва́льно і просла́влено і́м'я Твоє́ во ві́ки, амі́нь.","Бу́ди, Го́споди, ми́лость Твоя́ на нас, я́коже упова́хом на Тя. Благослове́н єси́, Го́споди, научи́ м'я оправда́нієм Твої́м. Благослове́н єси́, Влади́ко, вразуми́ м'я оправда́нієм Твої́м. Благослове́н єси́, Святи́й, просвіти́ м'я оправда́нії Твої́ми. Го́споди, ми́лость Твоя́ во вік, діл руку́ Твоє́ю не пре́зри: Тебі́ подоба́єть хвала́, Тебі́ подоба́єть пі́ніє, Тебі́ сла́ва подоба́єть, Отцю́, і Си́ну, і Свято́му Ду́ху, ни́ні і при́сно, і во ві́ки віко́в, амі́нь."]},{"h":"І читаємо сповідання православної віри","ps":["Ві́рую во єди́наго Бо́га Отця́ Вседержи́теля, Творця́ не́бу і землі́, ви́димим же всім і неви́димим. І во єди́наго Го́спода Ісу́са Христа́, Си́на Бо́жия, Єдиноро́днаго, І́же от Отця́ рожде́ннаго пре́жде всіх вік. Сві́та от Сві́та, Бо́га і́стинна от Бо́га і́стинна, рожде́нна, несотворе́нна, єдиносу́щна Отцю́, І́мже вся би́ша. Нас ра́ди челові́к і на́шего ра́ди спасе́нія сше́дшаго с небе́с і воплоти́вшагося от Ду́ха Свя́та і Марі́ї Ді́ви і вочелові́чшася. Расп'я́таго же за ни при Понті́йстім Пила́ті, і страда́вша, і погребе́нна. І воскре́сшаго в тре́тій день по Писа́нієм. І возше́дшаго на Небеса́, і сідя́ща одесну́ю Отця́. І па́ки гряду́щаго со сла́вою суди́ти живи́м і ме́ртвим, Єго́же Ца́рствію не бу́деть конця́. І в Ду́ха Свята́го, Го́спода, Животворя́щаго, І́же от Отця́ ісходя́щаго, І́же со Отце́м і Си́ном спокланя́єма і ссла́вима, глаго́лавшаго проро́ки. Во єди́ну Святу́ю, Собо́рную і Апо́стольськую Це́рков. Іспові́дую єди́но креще́ніє во оставле́ніє гріхо́в. Ча́ю воскресе́нія ме́ртвих, і жи́зні бу́дущаго ві́ка. Амі́нь."]},{"h":"Потім читаємо канони за уставом","ps":["Посе́м глаго́лем: Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, / Присноблаже́нную і Пренепоро́чную і Ма́тер Бо́га на́шего. / Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю Тя велича́єм.","Трисвято́є. По О́тче наш: Священник: Я́ко Твоє́ єсть Ца́рство: І ми: Амі́нь.","§Тропар святого дня, і храму, і поточний. [Якщо ж празник, промовляй лише кондак празника.]"]},{"h":"У неділю ввечері, глас 4","ps":["Небе́сних во́їнств Архістрати́зі, / мо́лим вас при́сно ми, недосто́йнії, / да ва́шими моли́твами оградите́ нас / кро́вом крил невеще́ственния ва́шея сла́ви, / сохраня́юще ни припа́дающия прилі́жно і вопію́щия: / от бід ізба́віте ни, / я́ко чинонача́льници Ви́шніх сил."]},{"h":"У понеділок ввечері, глас 2","ps":["Па́м'ять пра́веднаго с похвала́ми, / тебі́ же довлі́єть свиді́тельство Госпо́днє, Предте́че: / показа́л бо ся єси́ воі́стину і проро́ков честні́йший, / я́ко і в струя́х крести́ти сподо́бился єси́ Пропові́даннаго. / Ті́мже за і́стину пострада́в, ра́дуяся, / благовісти́л єси́ і су́щим во а́ді Бо́га, я́вльшагося пло́тію, / взе́млющаго гріх ми́ра / і подаю́щаго нам ве́лію ми́лость."]},{"h":"У вівторок і четвер ввечері, глас 1","ps":["Спаси́, Го́споди, лю́ди Твоя́ / і благослови́ достоя́ніє Твоє́, / побі́ди на сопроти́вния да́руя / і Твоє́ сохраня́я Кресто́м Твої́м жи́тельство."]},{"h":"У середу ввечері, глас 3","ps":["Апо́столи святі́ї, / молі́те Ми́лостиваго Бо́га, / да прегріше́ній оставле́ніє / пода́сть душа́м на́шим."]},{"h":"І святителю Миколаю тропар, глас 4","ps":["Пра́вило ві́ри і о́браз кро́тости, / воздержа́нія учи́теля / яви́ тя ста́ду твоєму́ / Я́же веще́й І́стина. / Сего́ ра́ди стяжа́л єси́ смире́нієм висо́кая, / нището́ю бога́тая, / о́тче священнонача́льниче Нико́лає, / моли́ Христа́ Бо́га, / спасти́ся душа́м на́шим."]},{"h":"Потім тропарі, глас 4","ps":["Бо́же оте́ць на́ших, / творя́й при́сно с на́ми по Твоє́й кро́тости, / не отста́ви ми́лость Твою́ от нас, / но моли́твами їх / в ми́рі упра́ви живо́т наш.","І́же во всем ми́рі му́ченик Твої́х, / я́ко багряни́цею і ви́ссом, / кровми́ Це́рков Твоя́ украси́вшися, / ті́ми вопіє́ть Ті, Христе́ Бо́же: / лю́дем Твої́м щедро́ти Твоя́ низпосли́, / мир жи́тельству Твоєму́ да́руй, / і душа́м на́шим ве́лію ми́лость.","Слава, глас 8: Со святи́ми упоко́й, / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная.","І нині: Моли́твами, Го́споди, всіх святи́х, і Богоро́диці, / Твой мир даждь нам і поми́луй нас, / я́ко Єди́н щедр."]},{"h":"У п’ятницю ввечері промовляй ці тропарі, глас 2","ps":["Апо́столи, му́ченици і проро́ци, / святи́теліє, преподо́бнії і пра́веднії, / до́брі по́двиг соверши́вшії і ві́ру соблю́дшії, / дерзнове́ніє іму́ще ко Спа́су, / о нас Того́, я́ко Бла́га, молі́те, / спасти́ся, мо́лимся, душа́м на́шим.","Слава, глас 8: Со святи́ми упоко́й, / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная.","І ни́ні, глас то́йже: Я́ко нача́тки єстества́, Насади́телю тва́рі, / вселе́нная прино́сить Ті, Го́споди, богоно́сния му́ченики, / тіх моли́твами в ми́рі глубо́ці / Це́рков Твою́, жи́тельство Твоє́, / Богоро́дицею соблюди́, Многоми́лостиве.","Го́споди поми́луй, 40.","І́же на вся́коє вре́м'я і на вся́кий час, на Небесі́ і на землі́, покланя́ємий і сла́вимий, Христе́ Бо́же, Долготерпіли́ве, Многоми́лостиве, Многоблагоутро́бне, І́же пра́ведния люб'я́й і грі́шния ми́луяй, І́же вся зови́й ко спасе́нію обіща́нія ра́ди бу́дущих благ. Сам, Го́споди, прийми́ і на́ша в час сей моли́тви і іспра́ви живо́т наш к за́повідем Твої́м, ду́ші на́ша освяти́, тілеса́ очи́сти, помишле́нія іспра́ви, ми́слі очи́сти і ізба́ви нас от вся́кия ско́рби, зол і болі́зней, огради́ нас святи́ми Твої́ми А́нгели, да ополче́нієм їх соблюда́єми і наставля́ємі, дости́гнем в соєдине́ніє ві́ри і в ра́зум непристу́пния Твоєя́ сла́ви, я́ко благослове́н єси́ во ві́ки віко́в, амі́нь.","Го́споди поми́луй, Три́жди. Сла́ва, і ни́ні:","Честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м, / без істлі́нія Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицю, Тя велича́єм.","І́менем Госпо́днім благослови́, о́тче.","Священник: Моли́твами святи́х оте́ць на́ших, Го́споди, Ісу́се Христе́, Бо́же наш, поми́луй нас.","І ми: Амі́нь."]},{"h":"І молебна молитва до Пресвятої Богородиці ченця Павла з обителі Євергетиди, тобто Благодійниці","ps":["Нескве́рная, Небла́зная, Нетлі́нная, Пречи́стая, Чи́стая Ді́во, Богоневі́сто Влади́чице, я́же Бо́га Сло́ва челові́ком пресла́вним Твої́м Рождество́м соєдини́вшая, і отри́нувшеєся єстество́ ро́да на́шего небе́сним совоку́пльшая: я́же ненаде́жних єди́на Наде́жда, і бори́мих по́моще, гото́воє заступле́ніє к Тебі́ притека́ющих, і всіх христия́н прибі́жище. Не гнуша́йся мене́ грі́шнаго, скве́рнаго, скве́рними по́мисли, і словеси́, і дія́ньми всего́ себе́ непотре́бна сотво́рша, і ра́зумом лі́ності сласте́й житія́ раба́ би́вша; но я́ко человіколюби́ваго Бо́га Ма́ти, человіколю́бне умилосе́рдися о мні грі́шнім і блу́днім, і прийми́ моє́, є́же от скве́рних усте́н приноси́моє Тебі́ моле́ніє, і Твоєго́ Си́на, і на́шего Влади́ку і Го́спода, ма́тернєє Твоє́ дерзнове́ніє употребля́ющи, моли́, да отве́рзеть і мні человіколю́бния утро́би Своєя́ бла́гости, і презрі́в моя́ безчи́сленная прегріше́нія, обрати́ть м'я к покая́нію, і Свої́х за́повідей ді́лателя іску́сна яви́ть м'я. І предста́ни мні при́сно, я́ко ми́лостивая, і милосе́рдая, і благолюби́вая, в настоя́щем у́бо житії́ те́плая Предста́тельнице і Помо́щнице, сопроти́вних наше́ствія отгоня́ющи, і ко спасе́нію наставля́ющи м'я: і во вре́м'я ісхо́да моєго́ окая́нную мою́ ду́шу соблюда́ющи, і те́мния зра́ки лука́вих бісо́в дале́че от нея́ отгоня́ющи: в стра́шний же день суда́ ві́чния м'я ізбавля́ющи му́ки, і неізрече́нния сла́ви Твоєго́ Си́на і Бо́га на́шего наслі́дника м'я показу́ющи. Ю́же і да улучу́, Влади́чице моя́, Пресвята́я Богоро́дице, Твої́м хода́тайством і заступле́нієм, благода́тію і человіколю́бієм Єдиноро́днаго Си́на Твоєго́, Го́спода і Бо́га і Спа́са на́шего Ісу́са Христа́. Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в, амі́нь."]},{"h":"Інша молитва до Господа нашого Ісуса Христа ченця Антіоха Пандекта","ps":["І даждь нам, Влади́ко, на сон гряду́щим поко́й ті́ла і душі́, і сохрани́ нас от мра́чнаго сна гріхо́внаго, і от вся́каго те́мнаго і нощна́го сладостра́стія: укроти́ стремле́нія страсте́й, угаси́ разжже́нния стрі́ли лука́ваго, я́же на ни льсти́вно дви́жимия: пло́ті на́шея воста́нія утоли́, і вся́коє земно́є і веще́ственноє на́ше мудрова́ніє успи́. І да́руй нам, Бо́же, бодр ум, цілому́др по́мисл, се́рдце трезвя́щеєся, сон лего́к і вся́каго сатанина́ мечта́нія ізміне́н. Возста́ви же нас во вре́м'я моли́тви утвержде́ни в за́повідіх Твої́х, і па́м'ять суде́б Твої́х в себі́ тве́рду іму́ща: всено́щноє славосло́віє нам да́руй, во є́же пі́ти і благослови́ти і сла́вити пречестно́є і великолі́поє і́м'я Твоє́, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в, амі́нь.","Пресла́вная Присноді́во, Ма́ти Христа́ Бо́га, принеси́ на́шу моли́тву Си́ну Твоєму́ і Бо́гу на́шему, да спасе́ть Тобо́ю ду́ші на́ша."]},{"h":"Інша молитва святого Іоанникія","ps":["Упова́ніє моє́ Оте́ць, прибі́жище моє́ Син, покро́в мой Дух Святи́й, Тро́йце Свята́я, сла́ва Тебі́.","Священник: Сла́ва Тебі́, Христе́ Бо́же, упова́ніє на́ше, сла́ва Тебі́.","Хор: Сла́ва, і ни́ні: Го́споди поми́луй, три́жди. Благослови́."]},{"h":"І священник звершує відпуст","ps":["Христо́с, і́стинний Бог наш, моли́твами Пречи́стия Своєя́ Ма́тере, преподо́бних і богоно́сних оте́ць на́ших, і всіх святи́х, поми́луєть і спасе́ть нас, я́ко Благ і Человіколю́бець.","І ми: Амі́нь."]},{"h":"Потім предстоятель, учинивши поклін до землі, говорить братії","ps":["Благослові́те, отці́ святі́ї, прості́те мі, грі́шному.","І бра́тія: Бог прости́ть ті, о́тче святи́й."]},{"h":"Священник же говорить","ps":["Помо́лимся о Вели́ком господи́ні і Отці́ на́шем, Святі́йшем Патріа́рхі І́м'ярік, і о господи́ні на́шем преосвяще́ннійшем митрополи́ті (іли́ архієпи́скопі, іли́ єпи́скопе) І́м'ярік, і всей во Христі́ бра́тії на́шей.","І ми: Го́споди поми́луй, На вся́кий стих.","О Богохрани́мій страні́ на́шей, властеіх і во́їнстві єя́.","О ненави́дящих і лю́б'ящих нас.","О ми́лующих і служа́щих нам.","О запові́давших нам, недосто́йним, моли́тися о них.","О ізбавле́нії пліне́нних.","О отше́дших отці́х і бра́тіях на́ших.","О в мо́рі пла́вающих.","О в не́мощіх лежа́щих.","Помо́лимся і о ізоби́лії плодо́в земни́х,","І о вся́кой душі́ христия́н правосла́вних.","Ублажі́м правосла́вния архієре́ї, і кти́тори свята́го хра́ма сего́ [святи́я оби́телі сея́].","Роди́телі на́ша, і вся пре́жде отше́дшия отці́ і бра́тію на́шу, зді лежа́щия, і повсю́ду правосла́вния.","Предстоя́тель: Рцем і о себі́ самі́х.","Го́споди поми́луй, Три́жди.","Моли́твами святи́х оте́ць на́ших, Го́споди Ісу́се Христе́, Бо́же наш, поми́луй нас.","І ми: Амі́нь.","§І брати починають — з правого й лівого хору по порядку, один за одним — творити поклін, просити й приймати прощення від предстоятеля, кажучи подібно:","Благослови́, о́тче святи́й, і прости́ м'я, грі́шнаго. І про́чая.","§Предстоятель стоїть посеред церкви, доки не звершиться все."]},{"h":"Прийнявши прощення від предстоятеля, ідемо до своїх келій, промовляючи цю молитву, яку може читати й кожна людина","ps":["Ненави́дящих і оби́дящих нас прости́, Го́споди, Человіколю́бче. Благотворя́щим благосотвори́. Бра́тіям і сро́дником на́шим да́руй я́же ко спасе́нію проше́нія і жизнь ві́чную. В не́мощіх су́щия посіти́ і ісціле́ніє да́руй. І́же в мо́рі упра́ви. С путеше́ствующими спутеше́ствуй. Служа́щим і ми́лующим нас, гріхо́в оставле́ніє да́руй. Запові́давших нам, недосто́йним, моли́тися о них, поми́луй по вели́цій Твоє́й ми́лості. Пом'яни́, Го́споди, пре́жде усо́пшия отці́ і бра́тію на́шу, і упоко́й я, іді́же присіща́єть світ лиця́ Твоєго́. Пом'яни́, Го́споди, бра́тій на́ших пліне́нних і ізба́ви я от вся́каго обстоя́нія. Пом'яни́, Го́споди, плодонося́щих і доброді́лающих во святи́х Твої́х це́рквах, і даждь їм я́же ко спасе́нію проше́нія і жизнь ві́чную. Пом'яни́, Го́споди, і нас, смире́нних і грі́шних і недосто́йних раб Твої́х, і просвіти́ наш ум сві́том ра́зума Твоєго́, і наста́ви нас на стезю́ за́повідей Твої́х. Моли́твами Пречи́стия Влади́чиці на́шея Богоро́диці і Присноді́ви Марі́ї і всіх Твої́х святи́х. Я́ко благослове́н єси́ во ві́ки віко́в. Амі́нь.","§Кінець малого повечір’я."]}],"notes":[]}];
export default D;
